INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_2_kor_u1_L02_basic#1','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C1',1,'mc','auto','작가의 의도로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X01','K6-2-u1-X02']::text[],false,'{"seq":1,"concept":"K6-2-u1-C1","difficulty":1,"kind":"mc","stem":"작가의 의도로 알맞은 것은 어느 것인가요?","options":[{"t":"작가가 글을 쓴 까닭과 읽는 사람이 느끼기를 바란 것","correct":true},{"t":"작품을 읽고 모두가 똑같이 내야 하는 답","mis":"K6-2-u1-X01"},{"t":"작가가 살던 때에 있었던 일의 기록","mis":"K6-2-u1-X01"},{"t":"작품에 나오는 어려운 낱말의 뜻","mis":"K6-2-u1-X02"}],"explanation":["작가의 의도는 쓴 사람 쪽에서 생각해요.","작가가 왜 썼는지, 읽는 사람이 무엇을 느끼기를 바랐는지가 의도예요.","모두가 똑같이 내야 하는 정답이 아니에요."]}'::jsonb),
('g6_2_kor_u1_L02_basic#2','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',1,'mc','auto','시조 「같이 건너세」에서 되풀이된 말은 어느 것인가요?',ARRAY['K6-2-u1-X03']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"시조 「같이 건너세」에서 되풀이된 말은 어느 것인가요?","options":[{"t":"또 한","correct":true},{"t":"길이 되고","mis":"K6-2-u1-X03"},{"t":"한 마을로","mis":"K6-2-u1-X03"},{"t":"건너오면","mis":"K6-2-u1-X03"}],"explanation":["「또 한 돌을」, 「또 한 사람」에 「또 한」이 두 번 나와요.","되풀이된 말은 그냥 지나가는 말이 아니라 눈여겨볼 표시예요.","작은 것이 하나씩 쌓이는 모습이 드러나요."],"asset":{"type":"passage","lines":["돌 하나 또 한 돌을 놓으면 길이 되고","그 길로 또 한 사람 건너오면 이웃이라","우리도 이같이 놓아 한 마을로 살리라"],"title":"시조 「같이 건너세」 — 한도경"}}'::jsonb),
('g6_2_kor_u1_L02_basic#3','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',1,'sa','auto','시조 「나루를 지켜」 첫째 줄에서 두 번 되풀이된 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u1-C2","difficulty":1,"kind":"sa","stem":"시조 「나루를 지켜」 첫째 줄에서 두 번 되풀이된 말을 쓰세요.","answer":["백 번","백번"],"explanation":["「이 나루 백 번 고쳐 백 번을 다시 매도」예요.","「백 번」이 두 번 나와요.","몇 번이 되어도 지키겠다는 뜻을 힘주어 말한 거예요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"},"mis":"K6-2-u1-X03"}'::jsonb),
('g6_2_kor_u1_L02_basic#4','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',1,'mc','auto','시조는 모두 몇 줄로 짓나요?',ARRAY['K6-2-u1-X17']::text[],false,'{"seq":4,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"시조는 모두 몇 줄로 짓나요?","options":[{"t":"세 줄","correct":true},{"t":"두 줄","mis":"K6-2-u1-X17"},{"t":"네 줄","mis":"K6-2-u1-X17"},{"t":"정해진 줄 수가 없어요","mis":"K6-2-u1-X17"}],"explanation":["시조는 고려 말부터 이어 온 우리 고유의 시예요.","정해진 글자 수에 맞추어 세 줄로 지어요.","줄 수가 정해져 있어 하고 싶은 말을 고르고 골라 담아요."]}'::jsonb),
('g6_2_kor_u1_L02_basic#5','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',2,'mc','auto','「백 번 고쳐 백 번을 다시 매도」에 담긴 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X02']::text[],false,'{"seq":5,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「백 번 고쳐 백 번을 다시 매도」에 담긴 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"몇 번이 되어도 나루를 계속 지키겠다는 뜻","correct":true},{"t":"나루를 정확히 백 번 고쳤다는 기록","mis":"K6-2-u1-X03"},{"t":"나루가 자주 고장 나서 불편하다는 불평","mis":"K6-2-u1-X02"},{"t":"나루를 헐고 새로 짓자는 부탁","mis":"K6-2-u1-X02"}],"explanation":["「백 번」을 두 번 되풀이해 힘을 주었어요.","실제 횟수가 아니라 「아무리 여러 번이라도」라는 뜻이에요.","나루를 지키려는 마음을 힘주어 드러냈어요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"}}'::jsonb),
('g6_2_kor_u1_L02_basic#6','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',2,'mc','auto','「나루를 지켜」가 「변할 줄이 있으랴」처럼 묻는 말로 끝맺은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X06','K6-2-u1-X17']::text[],false,'{"seq":6,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「나루를 지켜」가 「변할 줄이 있으랴」처럼 묻는 말로 끝맺은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"답을 바라는 물음이 아니라 「변하지 않는다」는 뜻을 힘주어 말하려고","correct":true},{"t":"읽는 사람에게 답을 알려 달라고 하려고","mis":"K6-2-u1-X03"},{"t":"작가도 자기 마음을 몰라서","mis":"K6-2-u1-X06"},{"t":"시조는 언제나 물음으로 끝나야 해서","mis":"K6-2-u1-X17"}],"explanation":["「변할 줄이 있으랴」는 「변할 리가 없다」는 뜻이에요.","묻는 꼴로 끝맺어 오히려 뜻을 세게 말해요.","힘주어 끝맺은 말은 작가의 뜻을 찾는 좋은 실마리예요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"}}'::jsonb),
('g6_2_kor_u1_L02_basic#7','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C2',2,'match','auto','시조의 표현과 그 표현에 담긴 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u1-C2","difficulty":2,"kind":"match","stem":"시조의 표현과 그 표현에 담긴 뜻을 알맞게 이으세요.","pairs":[{"l":"돌 하나 또 한 돌을","r":"작은 것이 쌓여 큰 것이 된다"},{"l":"건너오면 이웃이라","r":"길이 이어지면 사람이 이어진다"},{"l":"변할 줄이 있으랴","r":"내 마음은 바뀌지 않는다"}],"mis":"K6-2-u1-X03","explanation":["되풀이하거나 힘준 표현에는 뜻이 담겨 있어요.","「또 한」의 되풀이는 쌓임, 「이웃」은 사람의 이어짐이에요.","「있으랴」는 묻는 꼴로 마음이 바뀌지 않음을 힘주어 말해요."]}'::jsonb),
('g6_2_kor_u1_L02_basic#8','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C3',2,'ox','auto','「한도경은 다리 놓는 사람이었으니까 이 시조는 다리를 놓자는 뜻이다. 끝.」 이렇게 읽으면 충분해요.',ARRAY['K6-2-u1-X04']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":2,"kind":"ox","stem":"「한도경은 다리 놓는 사람이었으니까 이 시조는 다리를 놓자는 뜻이다. 끝.」 이렇게 읽으면 충분해요.","answer":"X","reason_options":[{"t":"작가의 삶은 실마리일 뿐, 다시 작품으로 돌아와 근거를 찾아야 하기 때문에","correct":true},{"t":"작가의 직업이 곧 작품의 뜻이기 때문에","mis":"K6-2-u1-X04"}],"mis":"K6-2-u1-X04","explanation":["작가의 삶을 알면 작품이 다시 보여요.","그렇다고 삶만 보고 뜻을 하나로 정하면 안 돼요.","「왜 ‘이웃’이라고 했을까?」처럼 작품으로 돌아와야 해요."]}'::jsonb),
('g6_2_kor_u1_L02_basic#9','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C1',2,'mc','auto','두 시조를 읽은 뒤 이 시간에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X07','K6-2-u1-X06','K6-2-u1-X05']::text[],false,'{"seq":9,"concept":"K6-2-u1-C1","difficulty":2,"kind":"mc","stem":"두 시조를 읽은 뒤 이 시간에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"각 작가가 무엇을 전하려 했는지 근거를 들어 짐작하기","correct":true},{"t":"다리를 놓는 것과 나루를 지키는 것 가운데 누가 옳은지 겨루기","mis":"K6-2-u1-X07"},{"t":"더 좋은 시조 하나만 골라 외우기","mis":"K6-2-u1-X06"},{"t":"작가의 이름만 외우기","mis":"K6-2-u1-X05"}],"explanation":["두 시조는 같은 일을 두고 서로 다른 뜻을 담았어요.","누가 옳은지 겨루면 작품이 아니라 내 결론을 말하게 돼요.","각자 무엇을 전하려 했는지 근거로 짐작해요."]}'::jsonb),
('g6_2_kor_u1_L02_basic#10','kor',6,2,'u1','L02','g6_2_kor_u1_L02_basic','lesson_basic','K6-2-u1-C3',3,'error','auto','작가 한도경이 여러 마을을 다니며 다리 놓는 일을 했다는 것을 알고 「같이 건너세」를 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X06']::text[],false,'{"seq":10,"concept":"K6-2-u1-C3","difficulty":3,"kind":"error","stem":"작가 한도경이 여러 마을을 다니며 다리 놓는 일을 했다는 것을 알고 「같이 건너세」를 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"예강 — 「작가가 다리 놓는 일을 했대. 그러니 이 시조는 더 읽지 않아도 돼.」","correct":true,"mis_target":"K6-2-u1-X04"},{"t":"슬찬 — 「작가의 삶을 알고 나니 ‘또 한 사람’이 다시 보여.」","mis":"K6-2-u1-X06"},{"t":"온새 — 「‘이웃’이라는 말을 보면 다리보다 사람 이야기를 하고 싶었던 것 같아.」","mis":"K6-2-u1-X06"}],"explanation":["작가의 삶은 읽기를 시작하게 하는 실마리예요.","슬찬과 온새는 삶을 알고 다시 작품의 말로 돌아왔어요.","예강은 삶만 보고 작품 읽기를 멈추었어요."]}'::jsonb),
('g6_2_kor_u1_L02_challenge#1','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C1',2,'sa','auto','작가가 글을 쓴 까닭과 읽는 사람이 느끼기를 바란 것을 무엇이라고 하나요? 「작가의 ○○」에서 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u1-C1","difficulty":2,"kind":"sa","stem":"작가가 글을 쓴 까닭과 읽는 사람이 느끼기를 바란 것을 무엇이라고 하나요? 「작가의 ○○」에서 ○○에 알맞은 두 글자를 쓰세요.","answer":["의도"],"explanation":["글에는 쓴 사람이 있어요.","쓴 까닭과 바란 것을 작품에 담아요.","이것을 작가의 의도라고 해요."],"mis":"K6-2-u1-X01"}'::jsonb),
('g6_2_kor_u1_L02_challenge#2','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C2',2,'mc','auto','시 「창문」에서 두 번 나온 말은 어느 것인가요?',ARRAY['K6-2-u1-X03']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"시 「창문」에서 두 번 나온 말은 어느 것인가요?","options":[{"t":"같은","correct":true},{"t":"창문 앞에","mis":"K6-2-u1-X03"},{"t":"밤이 되자","mis":"K6-2-u1-X03"},{"t":"바뀐다","mis":"K6-2-u1-X03"}],"explanation":["「같은 유리 / 같은 자리」에 「같은」이 두 번 나와요.","달라진 것이 없다는 것을 힘주어 말해요.","그런데도 보이는 것이 바뀐다는 데에 눈길이 가요."],"asset":{"type":"passage","lines":["낮에는 밖을 보여 주더니","밤이 되자 나를 보여 준다.","같은 유리 / 같은 자리에 서 있는데","보이는 것이 바뀐다.","그래서 나는 밤마다","창문 앞에 오래 서 있는다."],"title":"「창문」 — 문해원"}}'::jsonb),
('g6_2_kor_u1_L02_challenge#3','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C3',3,'mc','auto','윤채겸은 나루에서 배를 젓던 사공의 딸이에요. 이것을 알고 「노 젓던 저 물길이 어디로 가겠는가」를 다시 읽었을 때 가장 알맞은 짐작은 어느 것인가요?',ARRAY['K6-2-u1-X08','K6-2-u1-X04']::text[],false,'{"seq":3,"concept":"K6-2-u1-C3","difficulty":3,"kind":"mc","stem":"윤채겸은 나루에서 배를 젓던 사공의 딸이에요. 이것을 알고 「노 젓던 저 물길이 어디로 가겠는가」를 다시 읽었을 때 가장 알맞은 짐작은 어느 것인가요?","options":[{"t":"나루에서 이어져 온 삶과 일이 쉽게 사라지지 않기를 바라는 마음","correct":true},{"t":"물길이 어디로 흐르는지 몰라 길을 묻는 마음","mis":"K6-2-u1-X08"},{"t":"사공의 딸이니 무조건 다리에 반대한다는 뜻","mis":"K6-2-u1-X04"},{"t":"노 젓는 방법을 알려 주려는 마음","mis":"K6-2-u1-X08"}],"explanation":["작가는 나루에서 마을 사람들의 사정을 들으며 자랐어요.","「노 젓던 저 물길」은 그 삶을 가리켜요.","「어디로 가겠는가」는 사라지지 않는다는 뜻을 힘주어 말해요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"}}'::jsonb),
('g6_2_kor_u1_L02_challenge#4','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C1',3,'ox','auto','같은 시를 읽고 친구와 생각이 다르면 둘 가운데 하나는 틀린 읽기예요.',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":4,"concept":"K6-2-u1-C1","difficulty":3,"kind":"ox","stem":"같은 시를 읽고 친구와 생각이 다르면 둘 가운데 하나는 틀린 읽기예요.","answer":"X","reason_options":[{"t":"둘 다 작품에서 근거를 댔다면 둘 다 좋은 읽기이기 때문에","correct":true},{"t":"작품의 뜻은 하나로 정해져 있기 때문에","mis":"K6-2-u1-X06"}],"mis":"K6-2-u1-X06","explanation":["예강은 「밤마다」, 「오래」를 근거로 외롭게 읽었어요.","슬찬은 「나를 보여 준다」를 근거로 반갑게 읽었어요.","근거가 있으면 서로 달라도 좋은 읽기예요."]}'::jsonb),
('g6_2_kor_u1_L02_challenge#5','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C2',3,'mc','auto','「창문」에서 「밤이 되자 / 나를 보여 준다」가 주는 느낌으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X08']::text[],false,'{"seq":5,"concept":"K6-2-u1-C2","difficulty":3,"kind":"mc","stem":"「창문」에서 「밤이 되자 / 나를 보여 준다」가 주는 느낌으로 알맞은 것은 어느 것인가요?","options":[{"t":"뜻밖의 것을 알아차린 느낌","correct":true},{"t":"한 번이 아니라 되풀이해 온 느낌","mis":"K6-2-u1-X03"},{"t":"창문이 깨질까 봐 걱정되는 느낌","mis":"K6-2-u1-X08"},{"t":"밖이 잘 보여 시원한 느낌","mis":"K6-2-u1-X08"}],"explanation":["낮에는 밖을 보여 주던 창문이에요.","밤이 되자 유리에 내가 비쳐 보여요.","같은 창문에서 뜻밖의 것을 알아차린 느낌이 들어요."],"asset":{"type":"passage","lines":["낮에는 밖을 보여 주더니","밤이 되자 나를 보여 준다.","같은 유리 / 같은 자리에 서 있는데","보이는 것이 바뀐다.","그래서 나는 밤마다","창문 앞에 오래 서 있는다."],"title":"「창문」 — 문해원"}}'::jsonb),
('g6_2_kor_u1_L02_challenge#6','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C1',3,'match','auto','「창문」을 읽은 두 친구의 생각과 그 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u1-C1","difficulty":3,"kind":"match","stem":"「창문」을 읽은 두 친구의 생각과 그 근거를 알맞게 이으세요.","pairs":[{"l":"예강 — 혼자라서 외로운 시","r":"「밤마다」, 「오래 서 있는다」"},{"l":"슬찬 — 드디어 나를 보게 된 반가운 시","r":"「나를 보여 준다」"},{"l":"두 읽기 모두","r":"시에서 근거를 들어 좋은 읽기"}],"mis":"K6-2-u1-X06","explanation":["같은 시를 읽고도 생각이 갈릴 수 있어요.","두 친구 모두 시에 적힌 말을 근거로 댔어요.","근거가 있으면 둘 다 좋은 읽기예요."]}'::jsonb),
('g6_2_kor_u1_L02_challenge#7','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C2',3,'error','auto','「나루를 지켜」의 「백 번」을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X06']::text[],false,'{"seq":7,"concept":"K6-2-u1-C2","difficulty":3,"kind":"error","stem":"「나루를 지켜」의 「백 번」을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「백 번은 나루를 실제로 고친 횟수를 적은 기록이야.」","correct":true,"mis_target":"K6-2-u1-X03"},{"t":"준희 — 「몇 번이 되어도 지키겠다는 뜻이야.」","mis":"K6-2-u1-X06"},{"t":"이현 — 「같은 말을 되풀이해서 힘을 준 거야.」","mis":"K6-2-u1-X06"}],"explanation":["「백 번」은 두 번 되풀이되어 힘을 주는 말이에요.","실제 횟수가 아니라 「아무리 여러 번이라도」라는 뜻이에요.","서아는 글자 그대로만 받아들였어요."],"asset":{"type":"passage","lines":["이 나루 백 번 고쳐 백 번을 다시 매도","노 젓던 저 물길이 어디로 가겠는가","나루를 향한 한마음 변할 줄이 있으랴"],"title":"시조 「나루를 지켜」 — 윤채겸"}}'::jsonb),
('g6_2_kor_u1_L02_challenge#8','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C3',4,'mc','auto','작가의 삶과 작품 읽기의 관계로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X05','K6-2-u1-X06']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":4,"kind":"mc","stem":"작가의 삶과 작품 읽기의 관계로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"작가의 삶을 실마리로 얻고, 다시 작품으로 돌아와 근거를 찾는다","correct":true},{"t":"작가의 삶을 알면 작품은 다시 읽지 않아도 된다","mis":"K6-2-u1-X04"},{"t":"작가의 삶은 작품과 상관없으니 알아보지 않는다","mis":"K6-2-u1-X05"},{"t":"작가의 삶과 다르게 읽으면 틀린 읽기이다","mis":"K6-2-u1-X06"}],"explanation":["작가를 아는 것과 작품을 읽는 것은 둘 다 필요해요.","삶은 실마리, 근거는 작품 안에서 찾아요.","둘 가운데 하나만 쓰면 감상이 얕아져요."]}'::jsonb),
('g6_2_kor_u1_L02_challenge#9','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C1',4,'mc','auto','두 시조에 담긴 작가의 의도를 바르게 짝지은 것은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X08','K6-2-u1-X02']::text[],false,'{"seq":9,"concept":"K6-2-u1-C1","difficulty":4,"kind":"mc","stem":"두 시조에 담긴 작가의 의도를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"「같이 건너세」 — 마을과 마을이 이어지기를 바람 / 「나루를 지켜」 — 이어져 온 삶을 쉽게 지우지 말자","correct":true},{"t":"「같이 건너세」 — 이어져 온 삶을 쉽게 지우지 말자 / 「나루를 지켜」 — 마을과 마을이 이어지기를 바람","mis":"K6-2-u1-X04"},{"t":"「같이 건너세」 — 나루를 새로 고치자 / 「나루를 지켜」 — 다리를 빨리 놓자","mis":"K6-2-u1-X08"},{"t":"두 시조 모두 — 강을 건너는 일은 위험하다","mis":"K6-2-u1-X02"}],"explanation":["「같이 건너세」의 근거는 「또 한」의 되풀이, 「이웃」, 「한 마을로 살리라」예요.","「나루를 지켜」의 근거는 「백 번」의 되풀이, 「변할 줄이 있으랴」예요.","근거를 들 수 있으면 좋은 짐작이에요."]}'::jsonb),
('g6_2_kor_u1_L02_challenge#10','kor',6,2,'u1','L02','g6_2_kor_u1_L02_challenge','lesson_challenge','K6-2-u1-C1',4,'essay','teacher','시조 「같이 건너세」와 「나루를 지켜」 가운데 하나를 골라, 작가의 의도를 짐작하고 시조에서 근거가 되는 표현을 두 가지 들어 쓰세요. 작가의 삶이 짐작에 어떻게 도움이 되었는지도 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u1-C1","difficulty":4,"kind":"essay","stem":"시조 「같이 건너세」와 「나루를 지켜」 가운데 하나를 골라, 작가의 의도를 짐작하고 시조에서 근거가 되는 표현을 두 가지 들어 쓰세요. 작가의 삶이 짐작에 어떻게 도움이 되었는지도 한 문장으로 쓰세요.","answer_guide":{"answer":"예(「같이 건너세」): 다리를 놓아 마을과 마을, 사람과 사람이 이어지기를 바라는 마음을 전하려 한 것 같다. 「돌 하나 또 한 돌을」, 「또 한 사람」처럼 「또 한」을 되풀이해 작은 것이 쌓이는 모습을 보여 주었고, 「건너오면 이웃이라」, 「한 마을로 살리라」라고 힘주어 끝맺었기 때문이다. 작가가 다리 놓는 일을 하며 물에 막힌 아이들을 보았다는 것을 알고 나니 「이웃」이라는 말이 사람 이야기로 다시 보였다.","scoring_points":["작가의 의도를 한 문장으로 짐작했는가","시조에서 근거가 되는 표현을 두 가지 들었는가","작가의 삶을 실마리로 쓰고 다시 작품의 말로 돌아왔는가"]},"explanation":["짐작 + 근거를 한 묶음으로 써요.","되풀이한 말과 힘준 끝맺음이 좋은 근거예요.","작가의 삶은 실마리로만 써요."]}'::jsonb),
('g6_2_kor_u1_L04_basic#1','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C2',1,'mc','auto','「돌아오는 길」에서 여러 번 나온 말은 어느 것인가요?',ARRAY['K6-2-u1-X02']::text[],false,'{"seq":1,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"「돌아오는 길」에서 여러 번 나온 말은 어느 것인가요?","options":[{"t":"걷는다","correct":true},{"t":"바다","mis":"K6-2-u1-X02"},{"t":"노래","mis":"K6-2-u1-X02"},{"t":"창문","mis":"K6-2-u1-X02"}],"explanation":["2연 「담을 따라 걷는다」, 4연 「걷는 것이 아니다」, 「길을 내려고 걷는다」예요.","「걷는다」가 되풀이되어 시의 뼈대가 돼요.","바다·노래·창문은 이 시에 없는 말이에요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb),
('g6_2_kor_u1_L04_basic#2','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',1,'mc','auto','「돌아오는 길」 2연의 「담」과 「닫힌 문」은 무엇을 나타낸다고 볼 수 있나요?',ARRAY['K6-2-u1-X08']::text[],false,'{"seq":2,"concept":"K6-2-u1-C4","difficulty":1,"kind":"mc","stem":"「돌아오는 길」 2연의 「담」과 「닫힌 문」은 무엇을 나타낸다고 볼 수 있나요?","options":[{"t":"나아가려는 사람을 막고 있는 것","correct":true},{"t":"사람이 사는 집의 생김새","mis":"K6-2-u1-X08"},{"t":"누군가 잃어버린 열쇠가 있는 곳","mis":"K6-2-u1-X08"},{"t":"비를 피할 수 있는 곳","mis":"K6-2-u1-X08"}],"explanation":["「담은 길고 문은 닫혀 있다」 — 둘이 나란히 놓였어요.","걷는 사람 앞이 막혀 있는 처지예요.","시어는 겉뜻보다 넓은 뜻을 품어요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb),
('g6_2_kor_u1_L04_basic#3','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',1,'ox','auto','시는 여러 번 읽을수록 처음에는 안 보이던 말이 보이기도 해요.',ARRAY['K6-2-u1-X08']::text[],false,'{"seq":3,"concept":"K6-2-u1-C4","difficulty":1,"kind":"ox","stem":"시는 여러 번 읽을수록 처음에는 안 보이던 말이 보이기도 해요.","answer":"O","reason_options":[{"t":"되풀이해 읽으면 낱말과 연 사이의 관계가 새로 보이기 때문에","correct":true},{"t":"시는 한 번 읽으면 뜻이 모두 드러나기 때문에","mis":"K6-2-u1-X08"}],"mis":"K6-2-u1-X08","explanation":["한 연씩 소리 내어 읽어 보아요.","두 번째 읽을 때 되풀이된 말이 들려요.","여러 번 읽는 것이 감상의 바탕이에요."]}'::jsonb),
('g6_2_kor_u1_L04_basic#4','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',1,'sa','auto','「돌아오는 길」은 모두 몇 연인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u1-C4","difficulty":1,"kind":"sa","stem":"「돌아오는 길」은 모두 몇 연인가요? 숫자로 쓰세요.","answer":["4","네"],"explanation":["연은 시에서 한 덩어리로 묶인 줄들이에요.","1연부터 4연까지 있어요.","연마다 걷는 사람의 처지가 조금씩 달라져요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"},"mis":"K6-2-u1-X17"}'::jsonb),
('g6_2_kor_u1_L04_basic#5','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',2,'match','auto','시구와 그렇게 읽은 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u1-C4","difficulty":2,"kind":"match","stem":"시구와 그렇게 읽은 근거를 알맞게 이으세요.","pairs":[{"l":"만져지는 것이 없다","r":"앞 줄에서 잃어버린 것을 세어 보았다"},{"l":"하늘만 넓다","r":"담은 길고 문은 닫혀 위밖에 열린 곳이 없다"},{"l":"남은 발자국이 길이 된다","r":"뒤를 돌아본 자리에 남은 것이 있었다"}],"mis":"K6-2-u1-X02","explanation":["시구의 뜻은 그 앞뒤 줄에서 근거를 찾아요.","1연은 잃은 것, 2연은 막힘, 3연은 남은 것이에요.","근거를 들면 짐작이 단단해져요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb),
('g6_2_kor_u1_L04_basic#6','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C3',2,'mc','auto','문해원은 어릴 때 집을 자주 옮겨 한 학교에 오래 다니지 못했고, 옮길 때마다 낯선 골목을 혼자 걸었으며 짐을 쌀 때마다 무언가를 두고 왔어요. 어른이 되어서는 오래 살 곳을 정하고 같은 골목을 날마다 걸으며 걷는 일에 대한 시를 썼어요. 이것을 알고 다시 읽을 때 새로 보이는 시구와 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X02']::text[],false,'{"seq":6,"concept":"K6-2-u1-C3","difficulty":2,"kind":"mc","stem":"문해원은 어릴 때 집을 자주 옮겨 한 학교에 오래 다니지 못했고, 옮길 때마다 낯선 골목을 혼자 걸었으며 짐을 쌀 때마다 무언가를 두고 왔어요. 어른이 되어서는 오래 살 곳을 정하고 같은 골목을 날마다 걸으며 걷는 일에 대한 시를 썼어요. 이것을 알고 다시 읽을 때 새로 보이는 시구와 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"「잃어버린 것」 — 이사할 때마다 두고 온 것들이 떠올라서","correct":true},{"t":"「하늘」 — 작가가 하늘 사진을 즐겨 찍어서","mis":"K6-2-u1-X02"},{"t":"「담」 — 작가의 집에는 담이 없어서","mis":"K6-2-u1-X02"},{"t":"「발자국」 — 작가가 달리기 선수여서","mis":"K6-2-u1-X02"}],"explanation":["작가는 짐을 쌀 때마다 무언가를 두고 왔어요.","그래서 「잃어버린 것을 세어 본다」가 그냥 나온 말이 아니겠구나 싶어요.","다른 보기는 작가의 삶에 나오지 않는 내용이에요."]}'::jsonb),
('g6_2_kor_u1_L04_basic#7','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C3',2,'mc','auto','「문해원이 이사를 자주 다녔대. 그러니까 이 시는 이사에 대한 시야. 다 풀렸어.」라고 말한 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X04','K6-2-u1-X05','K6-2-u1-X06']::text[],false,'{"seq":7,"concept":"K6-2-u1-C3","difficulty":2,"kind":"mc","stem":"「문해원이 이사를 자주 다녔대. 그러니까 이 시는 이사에 대한 시야. 다 풀렸어.」라고 말한 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"작가의 삶은 실마리일 뿐이야. 시의 어느 줄이 그렇게 읽히는지 근거를 함께 들어야 해.","correct":true},{"t":"맞아. 작가의 삶을 알았으니 이제 시는 더 읽지 않아도 돼.","mis":"K6-2-u1-X04"},{"t":"작가의 삶은 시와 상관없으니 아예 알아보지 않는 게 좋아.","mis":"K6-2-u1-X05"},{"t":"이사가 아니라 여행에 대한 시라고 정해 두자.","mis":"K6-2-u1-X06"}],"explanation":["작가의 삶은 시를 다시 보게 하는 실마리예요.","실마리를 얻은 뒤에는 내가 읽고 느낀 것과 견주어요.","근거는 언제나 시 안에서 찾아요."]}'::jsonb),
('g6_2_kor_u1_L04_basic#8','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',2,'ox','auto','「나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다」에서 「나」는 잃은 것을 찾으려고 걸어요.',ARRAY['K6-2-u1-X02']::text[],false,'{"seq":8,"concept":"K6-2-u1-C4","difficulty":2,"kind":"ox","stem":"「나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다」에서 「나」는 잃은 것을 찾으려고 걸어요.","answer":"X","reason_options":[{"t":"「찾으려고 걷는 것이 아니다」라고 하고 길을 내려고 걷는다고 했기 때문에","correct":true},{"t":"1연에서 잃어버린 것을 세어 보았기 때문에","mis":"K6-2-u1-X02"}],"mis":"K6-2-u1-X02","explanation":["4연은 「~이 아니다」로 앞의 생각을 뒤집어요.","걷는 까닭은 「길을 내려고」예요.","1연만 보고 판단하면 시의 흐름을 놓쳐요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb),
('g6_2_kor_u1_L04_basic#9','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C4',2,'mc','auto','「남은 발자국이 길이 된다」를 읽은 것으로 시에서 근거를 댈 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u1-X08','K6-2-u1-X02']::text[],false,'{"seq":9,"concept":"K6-2-u1-C4","difficulty":2,"kind":"mc","stem":"「남은 발자국이 길이 된다」를 읽은 것으로 시에서 근거를 댈 수 있는 것은 어느 것인가요?","options":[{"t":"걸어온 자국이 다음에 걸을 길이 된다","correct":true},{"t":"발자국이 지저분하게 남아 있다는 불평","mis":"K6-2-u1-X08"},{"t":"길을 잃어서 되돌아가야 한다는 걱정","mis":"K6-2-u1-X02"},{"t":"작가가 발자국 화석을 좋아했다는 뜻","mis":"K6-2-u1-X02"}],"explanation":["3연에서 걸어온 뒤를 돌아보니 발자국이 남아 있어요.","그 발자국이 길이 된다고 했어요.","잃기만 한 것이 아니라 남은 것도 있다는 뜻으로 읽을 수 있어요."],"asset":{"type":"passage","lines":["(1연) 잃어버린 것을 세어 본다 / 주머니에 손을 넣으면 / 만져지는 것이 없다","(2연) 담을 따라 걷는다 / 담은 길고 문은 닫혀 있다 / 닫힌 문 위로 하늘만 넓다","(3연) 걸어온 뒤를 돌아본다 / 발자국이 남아 있다 / 남은 발자국이 길이 된다","(4연) 나는 잃은 것을 찾으려고 / 걷는 것이 아니다 / 길을 내려고 걷는다"],"title":"「돌아오는 길」 — 문해원"}}'::jsonb),
('g6_2_kor_u1_L04_basic#10','kor',6,2,'u1','L04','g6_2_kor_u1_L04_basic','lesson_basic','K6-2-u1-C1',3,'mc','auto','시를 읽고 짐작한 작가의 의도를 말하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X06','K6-2-u1-X04']::text[],false,'{"seq":10,"concept":"K6-2-u1-C1","difficulty":3,"kind":"mc","stem":"시를 읽고 짐작한 작가의 의도를 말하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"짐작한 의도와 그 근거가 된 시구를 한 묶음으로 말한다","correct":true},{"t":"근거 없이 느낌만 짧게 말한다","mis":"K6-2-u1-X06"},{"t":"작가의 삶만 말하고 시의 말은 들지 않는다","mis":"K6-2-u1-X04"},{"t":"친구가 말한 짐작을 그대로 따라 한다","mis":"K6-2-u1-X06"}],"explanation":["짐작 + 근거를 한 묶음으로 말하면 다른 사람도 내 짐작을 따라올 수 있어요.","근거는 되풀이된 말이나 힘준 시구에서 찾아요.","작가의 삶은 실마리로 덧붙여요."]}'::jsonb),
('g6_2_kor_u1_L04_challenge#1','kor',6,2,'u1','L04','g6_2_kor_u1_L04_challenge','lesson_challenge','K6-2-u1-C4',2,'sa','auto','시에 쓰인 말을 무엇이라고 하나요? 두 글자로 쓰세요. (예: 「길」, 「담」, 「발자국」)','{}'::text[],false,'{"seq":1,"concept":"K6-2-u1-C4","difficulty":2,"kind":"sa","stem":"시에 쓰인 말을 무엇이라고 하나요? 두 글자로 쓰세요. (예: 「길」, 「담」, 「발자국」)","answer":["시어"],"explanation":["시에 쓰인 말을 시어라고 해요.","시어는 여러 뜻을 품는 일이 많아요.","「길」은 걷는 길도, 살아가는 날들도 될 수 있어요."],"mis":"K6-2-u1-X17"}'::jsonb),
