('g6_2_kor_u1_review_a#7','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C7',1,'mc','auto','「거들다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X15']::text[],false,'{"seq":7,"concept":"K6-2-u1-C7","difficulty":1,"kind":"mc","stem":"「거들다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"남이 하는 일을 옆에서 도와주다","correct":true},{"t":"남의 일을 방해하다","mis":"K6-2-u1-X15"},{"t":"혼자 끝까지 하다","mis":"K6-2-u1-X15"},{"t":"일을 뒤로 미루다","mis":"K6-2-u1-X15"}],"explanation":["「거드는 사람도 말리는 사람도 없었다」에 나와요.","돕는다는 뜻이에요.","앞뒤 문장이 뜻을 알려 줘요."]}'::jsonb),
('g6_2_kor_u1_review_a#8','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C3',1,'ox','auto','작가의 삶을 알면 작품의 뜻이 하나로 정해져요.',ARRAY['K6-2-u1-X04']::text[],false,'{"seq":8,"concept":"K6-2-u1-C3","difficulty":1,"kind":"ox","stem":"작가의 삶을 알면 작품의 뜻이 하나로 정해져요.","answer":"X","reason_options":[{"t":"작가의 삶은 실마리일 뿐이고 근거는 작품에서 찾아야 하기 때문에","correct":true},{"t":"작가가 쓴 대로만 읽어야 하기 때문에","mis":"K6-2-u1-X04"}],"mis":"K6-2-u1-X04","explanation":["작가의 삶은 읽기를 시작하게 하는 실마리예요.","뜻을 하나로 정해 주지 않아요.","작품으로 돌아와 근거를 찾아요."]}'::jsonb),
('g6_2_kor_u1_review_a#9','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C2',2,'mc','auto','「우산」에서 「덮는다」가 처음과 끝에 되풀이되어 생기는 효과로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X03','K6-2-u1-X02']::text[],false,'{"seq":9,"concept":"K6-2-u1-C2","difficulty":2,"kind":"mc","stem":"「우산」에서 「덮는다」가 처음과 끝에 되풀이되어 생기는 효과로 알맞은 것은 어느 것인가요?","options":[{"t":"한 번이 아니라 되풀이해 온 일임이 드러난다","correct":true},{"t":"시를 읽는 데 걸리는 시간이 길어진다","mis":"K6-2-u1-X03"},{"t":"우산의 색깔을 자세히 알려 준다","mis":"K6-2-u1-X02"},{"t":"비가 그쳤음을 알려 준다","mis":"K6-2-u1-X02"}],"explanation":["1연과 4연에 「남을 덮는다」가 나와요.","4연에는 「또」가 붙어요.","비가 올 때마다 되풀이되는 일임이 드러나요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb),
('g6_2_kor_u1_review_a#10','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C4',2,'mc','auto','「우산」의 「네 어깨는 젖는다」가 나타낸다고 볼 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u1-X08']::text[],false,'{"seq":10,"concept":"K6-2-u1-C4","difficulty":2,"kind":"mc","stem":"「우산」의 「네 어깨는 젖는다」가 나타낸다고 볼 수 있는 것은 어느 것인가요?","options":[{"t":"남을 위하느라 자기는 힘들고 손해를 보는 것","correct":true},{"t":"우산이 고장 났다는 것","mis":"K6-2-u1-X08"},{"t":"비가 그쳤다는 것","mis":"K6-2-u1-X08"},{"t":"어깨가 아픈 병이 있다는 것","mis":"K6-2-u1-X08"}],"explanation":["우산은 남을 덮어 주어요.","그동안 자기 어깨는 젖어요.","남을 돕느라 자기는 힘든 모습을 떠올리게 해요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb),
('g6_2_kor_u1_review_a#11','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C1',2,'mc','auto','「우산」을 읽고 예강은 「남을 덮느라 자기는 젖는 부모님 이야기 같아.」, 슬찬은 「끝나면 구석에서 마른다는 게 티 나지 않는 일을 하는 사람 이야기 같아.」라고 했어요. 두 읽기에 대한 생각으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":11,"concept":"K6-2-u1-C1","difficulty":2,"kind":"mc","stem":"「우산」을 읽고 예강은 「남을 덮느라 자기는 젖는 부모님 이야기 같아.」, 슬찬은 「끝나면 구석에서 마른다는 게 티 나지 않는 일을 하는 사람 이야기 같아.」라고 했어요. 두 읽기에 대한 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 시에서 근거를 들었으니 둘 다 좋은 읽기다","correct":true},{"t":"작가는 하나만 생각했을 테니 하나는 틀렸다","mis":"K6-2-u1-X06"},{"t":"시에 「부모님」이라는 말이 없으니 예강이 틀렸다","mis":"K6-2-u1-X06"},{"t":"둘 다 느낌일 뿐 근거가 없다","mis":"K6-2-u1-X06"}],"explanation":["예강은 「남을 덮는다」, 「어깨는 젖는다」를 근거로 댔어요.","슬찬은 「구석에서 마른다」를 근거로 댔어요.","근거가 있으면 서로 달라도 좋은 읽기예요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb),
('g6_2_kor_u1_review_a#12','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C5',2,'match','auto','이야기 구조와 「마지막 버스」의 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u1-C5","difficulty":2,"kind":"match","stem":"이야기 구조와 「마지막 버스」의 내용을 알맞게 이으세요.","pairs":[{"l":"발단","r":"하루 세 번 다니는 버스와 경적을 울리던 아저씨"},{"l":"전개","r":"마지막 버스가 없어져 하은이 한 시간을 걸었다"},{"l":"절정","r":"어른들이 고개를 저어도 하은이 한 달 동안 사람 수를 적었다"},{"l":"결말","r":"편지에 이름이 모여 마지막 버스가 다시 다녔다"}],"mis":"K6-2-u1-X09","explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb),
('g6_2_kor_u1_review_a#13','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C6',2,'mc','auto','「마지막 버스」의 줄거리를 잘 간추린 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11']::text[],false,'{"seq":13,"concept":"K6-2-u1-C6","difficulty":2,"kind":"mc","stem":"「마지막 버스」의 줄거리를 잘 간추린 것은 어느 것인가요?","options":[{"t":"마지막 버스가 없어져 마을 사람들이 불편해지자 하은이 한 달 동안 기다리는 사람 수를 적어 함께 편지를 쓰자고 했고, 어른들이 이름을 적어 버스가 다시 다니게 되었다","correct":true},{"t":"버스가 있었다. 봄이었다. 공책이 있었다. 편지를 썼다.","mis":"K6-2-u1-X10"},{"t":"하은은 정말 착한 아이다.","mis":"K6-2-u1-X11"},{"t":"산골 마을에서 읍내로 가는 버스는 하루 세 번 다녔다. 봉식 아저씨는…(처음부터 그대로)","mis":"K6-2-u1-X11"}],"explanation":["잘 간추린 줄거리는 사건끼리 이어져 있어요.","「~자 ~했고 ~해」처럼 까닭이 보여요.","늘어놓기·느낌·통째 옮기기는 간추린 것이 아니에요."]}'::jsonb),
('g6_2_kor_u1_review_a#14','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C7',2,'mc','auto','「마지막 버스」에서 마지막 버스가 없어진 때는 언제인가요?',ARRAY['K6-2-u1-X16']::text[],false,'{"seq":14,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「마지막 버스」에서 마지막 버스가 없어진 때는 언제인가요?","options":[{"t":"그해 봄","correct":true},{"t":"이듬달 첫날","mis":"K6-2-u1-X16"},{"t":"한 달 동안","mis":"K6-2-u1-X16"},{"t":"하루 세 번","mis":"K6-2-u1-X16"}],"explanation":["「그해 봄, 버스 회사는 … 마지막 버스를 없앴다.」","「이듬달 첫날」은 다시 다닌 날이에요.","시간을 나타내는 표현으로 일의 차례를 가려요."],"asset":{"type":"passage","lines":["그해 봄, 버스 회사는 손님이 적다며 마지막 버스를 없앴다.","읍내에서 늦게 끝나는 하은은 한 시간을 걸어 돌아왔다.","장 보러 간 어른들도 해 지기 전에 서둘러야 했다."],"title":"「마지막 버스」 둘"}}'::jsonb),
('g6_2_kor_u1_review_a#15','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C7',2,'mc','auto','「그런다고 회사가 들어주겠니.」라는 말을 듣고도 하은이 계속 적은 데서 알 수 있는 마음은 어느 것인가요?',ARRAY['K6-2-u1-X12']::text[],false,'{"seq":15,"concept":"K6-2-u1-C7","difficulty":2,"kind":"mc","stem":"「그런다고 회사가 들어주겠니.」라는 말을 듣고도 하은이 계속 적은 데서 알 수 있는 마음은 어느 것인가요?","options":[{"t":"마을 사람들의 불편을 꼭 바꾸고 싶은 굳은 마음","correct":true},{"t":"어른들을 골탕 먹이려는 마음","mis":"K6-2-u1-X12"},{"t":"공책을 빨리 다 쓰고 싶은 마음","mis":"K6-2-u1-X12"},{"t":"버스 기사가 되고 싶은 마음","mis":"K6-2-u1-X12"}],"explanation":["하은은 자기도, 어른들도 불편해진 것을 겪었어요.","반대하는 말을 듣고도 한 달 동안 적었어요.","앞뒤 사건이 마음을 짐작하는 근거예요."],"asset":{"type":"passage","lines":["하은은 날마다 정류장에서 기다리는 사람 수를 공책에 적었다.","「그런다고 회사가 들어주겠니.」 어른들은 고개를 저었다.","그래도 하은은 한 달 동안 하루도 빼지 않고 적었다.","공책 마지막 장에 「같이 편지를 써 주세요」라고 썼다."],"title":"「마지막 버스」 셋"}}'::jsonb),
('g6_2_kor_u1_review_a#16','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C8',2,'mc','auto','「마지막 버스」를 소개하는 글의 「처음」으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X13','K6-2-u1-X11']::text[],false,'{"seq":16,"concept":"K6-2-u1-C8","difficulty":2,"kind":"mc","stem":"「마지막 버스」를 소개하는 글의 「처음」으로 알맞은 것은 어느 것인가요?","options":[{"t":"「마지막 버스」는 없어진 버스를 다시 다니게 한 아이의 이야기입니다. 저도 버스로 학원에 다녀서 이 이야기를 골랐습니다.","correct":true},{"t":"완전 강추! 무조건 읽으세요!","mis":"K6-2-u1-X13"},{"t":"이 책은 150쪽이고 값은 8000원입니다.","mis":"K6-2-u1-X13"},{"t":"결국 버스가 다시 다니고 아저씨가 경적을 두 번 울리며 끝납니다.","mis":"K6-2-u1-X11"}],"explanation":["처음에는 무슨 작품인지와 고른 까닭을 써요.","광고나 값은 작품을 알려 주지 않아요.","결말을 다 말하면 읽는 즐거움을 빼앗아요."]}'::jsonb),
('g6_2_kor_u1_review_a#17','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C3',3,'mc','auto','정다온은 어릴 때 형편이 어려워 연필 한 자루를 오래 아껴 썼습니다. 지금은 아이들에게 글쓰기를 가르치며, 다 쓴 연필을 버리지 않고 모아 둔다고 합니다. 이것을 알고 「다 닳은 연필을 / 버리지 못하고」를 다시 읽을 때 가장 알맞은 짐작은 어느 것인가요?',ARRAY['K6-2-u1-X08','K6-2-u1-X04','K6-2-u1-X02']::text[],false,'{"seq":17,"concept":"K6-2-u1-C3","difficulty":3,"kind":"mc","stem":"정다온은 어릴 때 형편이 어려워 연필 한 자루를 오래 아껴 썼습니다. 지금은 아이들에게 글쓰기를 가르치며, 다 쓴 연필을 버리지 않고 모아 둔다고 합니다. 이것을 알고 「다 닳은 연필을 / 버리지 못하고」를 다시 읽을 때 가장 알맞은 짐작은 어느 것인가요?","options":[{"t":"어려운 때를 함께한 작은 것을 소중히 여기는 마음을 전하려 한 것 같다","correct":true},{"t":"연필을 많이 사 두자는 뜻이다","mis":"K6-2-u1-X08"},{"t":"작가가 선생님이니 공부를 열심히 하라는 뜻이다. 끝.","mis":"K6-2-u1-X04"},{"t":"연필은 다 쓰면 바로 버려야 한다는 뜻이다","mis":"K6-2-u1-X02"}],"explanation":["작가는 연필 한 자루를 오래 아껴 썼어요.","그래서 「버리지 못하고」가 그냥 나온 말이 아니겠구나 싶어요.","삶은 실마리, 근거는 「필통 맨 앞에 둔다」 같은 시구예요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb),
('g6_2_kor_u1_review_a#18','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C1',3,'error','auto','「연필」을 읽고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X01','K6-2-u1-X06']::text[],false,'{"seq":18,"concept":"K6-2-u1-C1","difficulty":3,"kind":"error","stem":"「연필」을 읽고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"서아 — 「작가가 생각한 뜻은 하나뿐이니 우리는 그 정답을 맞혀야 해.」","correct":true,"mis_target":"K6-2-u1-X01"},{"t":"준희 — 「‘손안에서 작아진다’를 보면 자기를 내어 주는 이야기 같아.」","mis":"K6-2-u1-X06"},{"t":"이현 — 「‘필통 맨 앞에 둔다’를 보면 고마운 마음이 느껴져.」","mis":"K6-2-u1-X06"}],"explanation":["작가의 의도는 맞혀야 하는 정답이 아니에요.","준희와 이현은 시구를 근거로 댔어요.","근거가 있으면 좋은 읽기예요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb),
('g6_2_kor_u1_review_a#19','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C6',3,'blank','auto','「마지막 버스가 없어져 마을 사람들이 불편해지자 (  ) 어른들이 함께 편지에 이름을 적어 버스가 다시 다니게 되었다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?',ARRAY['K6-2-u1-X09','K6-2-u1-X11','K6-2-u1-X10']::text[],false,'{"seq":19,"concept":"K6-2-u1-C6","difficulty":3,"kind":"blank","stem":"「마지막 버스가 없어져 마을 사람들이 불편해지자 (  ) 어른들이 함께 편지에 이름을 적어 버스가 다시 다니게 되었다.」 빈칸에 들어갈 말로 흐름이 가장 잘 이어지는 것은 어느 것인가요?","options":[{"t":"하은이 한 달 동안 기다리는 사람 수를 적어 함께 편지를 쓰자고 했고,","correct":true},{"t":"봉식 아저씨가 경적을 한 번 더 울렸고,","mis":"K6-2-u1-X09"},{"t":"하은은 한 시간을 걸어 돌아왔고,","mis":"K6-2-u1-X11"},{"t":"그해 봄이 왔고,","mis":"K6-2-u1-X10"}],"explanation":["빈칸에는 절정의 사건이 들어가요.","하은의 공책이 어른들의 이름으로 이어져요.","다른 보기는 흐름을 잇지 못해요."]}'::jsonb),
('g6_2_kor_u1_review_a#20','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C5',3,'error','auto','「마지막 버스」의 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X09','K6-2-u1-X06']::text[],false,'{"seq":20,"concept":"K6-2-u1-C5","difficulty":3,"kind":"error","stem":"「마지막 버스」의 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「버스가 다시 다니는 곳이 절정이야. 가장 기쁘니까.」","correct":true,"mis_target":"K6-2-u1-X09"},{"t":"준희 — 「어른들이 고개를 저어도 하은이 한 달을 적은 곳이 절정이야.」","mis":"K6-2-u1-X06"},{"t":"이현 — 「마지막 버스가 없어진 곳부터 전개야.」","mis":"K6-2-u1-X06"}],"explanation":["절정은 가장 기쁜 곳이 아니라 갈등이 가장 두드러지는 곳이에요.","버스가 다시 다니는 곳은 결말이에요.","준희와 이현은 바르게 말했어요."]}'::jsonb),
('g6_2_kor_u1_review_a#21','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C9',3,'match','auto','「쓰다」가 쓰인 문장과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":21,"concept":"K6-2-u1-C9","difficulty":3,"kind":"match","stem":"「쓰다」가 쓰인 문장과 뜻을 알맞게 이으세요.","pairs":[{"l":"편지를 쓰다","r":"글씨로 적다"},{"l":"모자를 쓰다","r":"머리에 얹다"},{"l":"약이 쓰다","r":"맛이 달지 않고 혀가 아리다"},{"l":"용돈을 쓰다","r":"돈을 들이다"}],"mis":"K6-2-u1-X15","explanation":["글자는 같지만 뜻이 네 가지예요.","함께 쓰인 말(편지·모자·약·용돈)이 뜻을 정해요.","앞뒤 말을 보고 가려 읽어요."]}'::jsonb),
('g6_2_kor_u1_review_a#22','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C8',3,'error','auto','작품 소개를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u1-X06','K6-2-u1-X13','K6-2-u1-X11']::text[],false,'{"seq":22,"concept":"K6-2-u1-C8","difficulty":3,"kind":"error","stem":"작품 소개를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「짐작한 의도는 근거 없이 써도 돼.」","correct":true,"mis_target":"K6-2-u1-X06"},{"t":"준희 — 「처음에는 고른 까닭을 써.」","mis":"K6-2-u1-X13"},{"t":"이현 — 「가운데에는 간추린 줄거리를 써.」","mis":"K6-2-u1-X11"}],"explanation":["짐작한 의도에는 근거를 함께 써요.","처음 — 고른 까닭, 가운데 — 줄거리와 의도예요.","준희와 이현은 바르게 말했어요."]}'::jsonb),
('g6_2_kor_u1_review_a#23','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C6',4,'mc','auto','「마지막 버스」의 줄거리를 두 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u1-X10','K6-2-u1-X11','K6-2-u1-X09']::text[],false,'{"seq":23,"concept":"K6-2-u1-C6","difficulty":4,"kind":"mc","stem":"「마지막 버스」의 줄거리를 두 문장으로 간추린 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마지막 버스가 없어져 마을 사람들이 불편해지자 하은이 한 달 동안 기다리는 사람 수를 적었다. 그 공책을 본 어른들이 함께 편지에 이름을 적어 이듬달 첫날 버스가 다시 다니게 되었다.","correct":true},{"t":"하은이 있었다. 버스가 있었다. 공책이 있었다. 편지가 있었다.","mis":"K6-2-u1-X10"},{"t":"하은은 착하고, 봉식 아저씨는 친절하다.","mis":"K6-2-u1-X11"},{"t":"버스는 하루 세 번 다녔다. 아저씨는 경적을 울렸다.","mis":"K6-2-u1-X09"}],"explanation":["두 문장 안에 네 부분의 중요한 사건이 다 들어가요.","「~자」, 「그 공책을 본」이 사건을 이어요.","「이듬달 첫날」로 때도 밝혀요."]}'::jsonb),
('g6_2_kor_u1_review_a#24','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C1',4,'essay','teacher','「우산」에서 짐작한 작가의 의도를 한 문장으로 쓰고, 그렇게 짐작한 근거가 되는 시구를 두 가지 드세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u1-C1","difficulty":4,"kind":"essay","stem":"「우산」에서 짐작한 작가의 의도를 한 문장으로 쓰고, 그렇게 짐작한 근거가 되는 시구를 두 가지 드세요.","answer_guide":{"answer":"예: 티 나지 않게 남을 돕는 사람의 마음과 그 고마움을 전하려 한 것 같다. 근거는 「너는 남을 덮는다」·「네 어깨는 젖는다」로 남을 위해 자기가 젖는 모습을 그린 것과, 「접힌 채로 구석에서 마른다」로 일이 끝나면 눈에 띄지 않는 곳에 놓이는 모습을 그린 것이다. 「덮는다」가 처음과 끝에 되풀이되어 이런 일이 계속됨을 드러낸다.","scoring_points":["의도를 한 문장으로 짐작했는가","근거 시구를 두 가지 들었는가","되풀이한 표현의 효과를 근거로 썼는가"]},"explanation":["짐작 + 근거가 한 묶음이에요.","「덮는다」의 되풀이가 좋은 근거예요.","근거가 있으면 다르게 읽어도 좋아요."],"asset":{"type":"passage","lines":["(1연) 비가 오면 / 너는 남을 덮는다","(2연) 덮는 동안 / 네 어깨는 젖는다","(3연) 덮는 일이 끝나면 / 너는 접힌다","접힌 채로 구석에서 마른다","(4연) 다음 비가 오면 / 너는 또 펴진다","또 남을 덮는다"],"title":"「우산」 — 문해원"}}'::jsonb),
('g6_2_kor_u1_review_a#25','kor',6,2,'u1','','g6_2_kor_u1_review_a','unit_review','K6-2-u1-C7',4,'essay','teacher','「마지막 버스」에서 시간을 나타내는 표현을 세 가지 찾아 쓰고, 그 표현을 써서 일이 일어난 차례대로 이야기를 세 문장으로 간추리세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u1-C7","difficulty":4,"kind":"essay","stem":"「마지막 버스」에서 시간을 나타내는 표현을 세 가지 찾아 쓰고, 그 표현을 써서 일이 일어난 차례대로 이야기를 세 문장으로 간추리세요.","answer_guide":{"answer":"예: 시간 표현 — 「하루 세 번」, 「그해 봄」, 「한 달 동안」, 「이듬달 첫날」 가운데 세 가지. 간추리기 — 그해 봄 버스 회사가 마지막 버스를 없앴다. 하은은 한 달 동안 정류장에서 기다리는 사람 수를 적어 같이 편지를 쓰자고 했다. 어른들이 편지에 이름을 적었고 이듬달 첫날 마지막 버스가 다시 다니기 시작했다.","scoring_points":["시간을 나타내는 표현을 세 가지 찾았는가","시간 표현을 써서 차례대로 간추렸는가","사건이 이어지게 썼는가"]},"explanation":["시간 표현은 일의 차례를 알려 줘요.","그해 봄 → 한 달 동안 → 이듬달 첫날이에요.","차례를 지키면 흐름이 또렷해져요."]}'::jsonb),
('g6_2_kor_u1_review_b#1','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C1',1,'mc','auto','같은 작품을 서로 다르게 읽었을 때 좋은 읽기인지 가리는 기준은 어느 것인가요?',ARRAY['K6-2-u1-X06']::text[],false,'{"seq":1,"concept":"K6-2-u1-C1","difficulty":1,"kind":"mc","stem":"같은 작품을 서로 다르게 읽었을 때 좋은 읽기인지 가리는 기준은 어느 것인가요?","options":[{"t":"작품에서 근거를 들었는가","correct":true},{"t":"작가와 똑같이 읽었는가","mis":"K6-2-u1-X06"},{"t":"더 많은 친구가 그렇게 읽었는가","mis":"K6-2-u1-X06"},{"t":"더 길게 말했는가","mis":"K6-2-u1-X06"}],"explanation":["작품의 주제는 한 사람의 답으로 정해지지 않아요.","맞고 틀림이 아니라 근거가 있고 없음이에요.","근거가 있으면 서로 달라도 좋은 읽기예요."]}'::jsonb),
('g6_2_kor_u1_review_b#2','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C2',1,'mc','auto','「연필」 1연에서 두 번 나온 말은 어느 것인가요?',ARRAY['K6-2-u1-X03']::text[],false,'{"seq":2,"concept":"K6-2-u1-C2","difficulty":1,"kind":"mc","stem":"「연필」 1연에서 두 번 나온 말은 어느 것인가요?","options":[{"t":"짧아","correct":true},{"t":"깎을","mis":"K6-2-u1-X03"},{"t":"글씨","mis":"K6-2-u1-X03"},{"t":"길어","mis":"K6-2-u1-X03"}],"explanation":["「짧아진다 / 짧아질수록」에 「짧아」가 두 번 나와요.","「짧아」와 「길어」가 맞서 있어요.","되풀이와 맞섬이 시의 뜻을 가리켜요."],"asset":{"type":"passage","lines":["(1연) 깎을수록 짧아진다 / 짧아질수록 / 글씨는 길어진다","(2연) 내가 쓴 공책은 두꺼워지고 / 연필은 / 손안에서 작아진다","(3연) 다 닳은 연필을 / 버리지 못하고 / 필통 맨 앞에 둔다"],"title":"「연필」 — 정다온"}}'::jsonb),
('g6_2_kor_u1_review_b#3','kor',6,2,'u1','','g6_2_kor_u1_review_b','unit_review','K6-2-u1-C5',1,'mc','auto','이야기 구조에서 이야기가 마무리되는 부분은 어느 것인가요?',ARRAY['K6-2-u1-X09']::text[],false,'{"seq":3,"concept":"K6-2-u1-C5","difficulty":1,"kind":"mc","stem":"이야기 구조에서 이야기가 마무리되는 부분은 어느 것인가요?","options":[{"t":"결말","correct":true},{"t":"발단","mis":"K6-2-u1-X09"},{"t":"전개","mis":"K6-2-u1-X09"},{"t":"절정","mis":"K6-2-u1-X09"}],"explanation":["발단은 시작, 전개는 사건이 본격적으로 생기는 부분이에요.","절정은 갈등이 가장 두드러지는 곳이에요.","결말에서 이야기가 마무리돼요."]}'::jsonb),
