('g6_2_kor_u2_review_d#13','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C8',2,'ox','auto','면담 내용을 정리할 때 들은 말을 한 마디도 빠뜨리지 않고 그대로 옮겨 적는 것이 가장 좋아요.',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":13,"concept":"K6-2-u2-C8","difficulty":2,"kind":"ox","stem":"면담 내용을 정리할 때 들은 말을 한 마디도 빠뜨리지 않고 그대로 옮겨 적는 것이 가장 좋아요.","answer":"X","reason_options":[{"t":"정리는 내가 듣고 이해한 것을 골라 내 말로 다시 세우는 일이기 때문에","correct":true},{"t":"그대로 옮겨야 뜻이 바뀌지 않기 때문에","mis":"K6-2-u2-X13"}],"mis":"K6-2-u2-X13","explanation":["통째로 옮기면 무엇이 중요한지 몰라요.","삭제·대체·선택·구성으로 간추려요.","뜻만 바꾸지 않으면 돼요."]}'::jsonb),
('g6_2_kor_u2_review_d#14','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C10',2,'error','auto','태건에게 할 질문을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":14,"concept":"K6-2-u2-C10","difficulty":2,"kind":"error","stem":"태건에게 할 질문을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서율 — 「곤란해해도 꼭 답하게 해야 진짜 면담이야.」","correct":true,"mis_target":"K6-2-u2-X17"},{"t":"도경 — 「답할 사람이 고를 여지를 남겨 두어야 해.」","mis":"K6-2-u2-X17"},{"t":"채원 — 「깎아내리는 말은 빼고 까닭을 여쭈어야 해.」","mis":"K6-2-u2-X17"}],"explanation":["억지로 답하게 하는 질문은 불쾌한 질문이에요.","도경과 채원은 바르게 말했어요.","궁금함과 배려를 함께 담아요."]}'::jsonb),
('g6_2_kor_u2_review_d#15','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C2',2,'match','auto','면담을 요청할 때 밝히는 것과 그 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K6-2-u2-C2","difficulty":2,"kind":"match","stem":"면담을 요청할 때 밝히는 것과 그 예를 알맞게 이으세요.","pairs":[{"l":"우리가 누구인지","r":"6학년 아침별 모둠입니다"},{"l":"면담 목적","r":"책방을 꾸리는 일을 알리는 글을 쓰려고 합니다"},{"l":"걸리는 시간","r":"삼십 분 정도면 될 것 같습니다"},{"l":"바라는 날짜","r":"다음 주 목요일 오후는 괜찮으실까요?"}],"mis":"K6-2-u2-X03","explanation":["이 네 가지를 밝혀야 상대가 정할 수 있어요.","날짜는 「괜찮으실까요?」로 여쭈어요.","정해서 알리지 않아요."]}'::jsonb),
('g6_2_kor_u2_review_d#16','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C8',2,'mc','auto','말 걸기를 어려워하는 친구가 모둠 면담에서 처음 맡기 좋은 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X19','K6-2-u2-X11']::text[],false,'{"seq":16,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"말 걸기를 어려워하는 친구가 모둠 면담에서 처음 맡기 좋은 일로 알맞은 것은 어느 것인가요?","options":[{"t":"메모나 정리를 맡아 함께한다","correct":true},{"t":"모둠에서 빠져 혼자 기다린다","mis":"K6-2-u2-X19"},{"t":"억지로 첫 질문을 크게 한다","mis":"K6-2-u2-X19"},{"t":"녹음 허락 없이 담는 일을 맡는다","mis":"K6-2-u2-X11"}],"explanation":["어려워하는 것은 잘못이 아니에요.","할 수 있는 만큼부터 함께해요.","메모·정리를 맡거나 지켜보는 것부터 시작해요."]}'::jsonb),
('g6_2_kor_u2_review_d#17','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C6',3,'error','auto','진로 면담 자료를 찾는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X09']::text[],false,'{"seq":17,"concept":"K6-2-u2-C6","difficulty":3,"kind":"error","stem":"진로 면담 자료를 찾는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「검색하면 맨 위에 나오는 자료가 가장 믿을 만해.」","correct":true,"mis_target":"K6-2-u2-X09"},{"t":"주호 — 「누가 만든 자료인지 확인해야 해.」","mis":"K6-2-u2-X09"},{"t":"서아 — 「언제 만든 자료인지도 살펴봐.」","mis":"K6-2-u2-X09"}],"explanation":["검색 순서는 믿을 만한지와 상관없어요.","누가·언제 만들었는지 확인해요.","주호와 서아는 바르게 말했어요."]}'::jsonb),
('g6_2_kor_u2_review_d#18','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C10',3,'error','auto','짝과 태건 면담 놀이를 했어요. 작품에 근거하지 않고 답한 친구는 누구인가요?',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":18,"concept":"K6-2-u2-C10","difficulty":3,"kind":"error","stem":"짝과 태건 면담 놀이를 했어요. 작품에 근거하지 않고 답한 친구는 누구인가요?","options":[{"t":"하윤 — 「(태건이 되어) 마을에서 상을 준다고 해서 돌을 옮겼어요.」","correct":true,"mis_target":"K6-2-u2-X16"},{"t":"지호 — 「(태건이 되어) 할머니가 한 시간을 돌아 다니시는 게 마음에 걸렸어요.」","mis":"K6-2-u2-X16"},{"t":"나은 — 「(태건이 되어) 그건 이야기에 나오지 않습니다.」","mis":"K6-2-u2-X16"}],"explanation":["상을 준다는 말은 이야기에 없어요.","지호는 이야기 속 사건으로 답했어요.","나은처럼 없는 것은 없다고 말해도 돼요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb),
('g6_2_kor_u2_review_d#19','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C9',3,'ox','auto','「면담이 재미있었다.」는 면담 과정을 성찰하는 말로 충분해요.',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":19,"concept":"K6-2-u2-C9","difficulty":3,"kind":"ox","stem":"「면담이 재미있었다.」는 면담 과정을 성찰하는 말로 충분해요.","answer":"X","reason_options":[{"t":"절차마다 무엇을 했는지 짚어 잘한 점·보완할 점·더 알고 싶은 점으로 나누어야 하기 때문에","correct":true},{"t":"재미있었으면 잘한 면담이기 때문에","mis":"K6-2-u2-X14"}],"mis":"K6-2-u2-X14","explanation":["막연한 기분으로는 다음에 할 일이 남지 않아요.","절차마다 짚어요.","세 항목으로 나누어 적어요."]}'::jsonb),
('g6_2_kor_u2_review_d#20','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C6',3,'error','auto','아침별 모둠이 질문을 점검하며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":20,"concept":"K6-2-u2-C6","difficulty":3,"kind":"error","stem":"아침별 모둠이 질문을 점검하며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「질문이 열 개를 넘으면 점검은 안 해도 돼.」","correct":true,"mis_target":"K6-2-u2-X07"},{"t":"다온 — 「목적에 맞는지부터 살펴보자.」","mis":"K6-2-u2-X07"},{"t":"소미 — 「‘그거’, ‘그때’ 같은 말은 뜻이 분명하게 바꾸자.」","mis":"K6-2-u2-X07"}],"explanation":["개수는 점검의 기준이 아니에요.","목적·예의·명료함을 살펴요.","다온과 소미는 바르게 말했어요."]}'::jsonb),
('g6_2_kor_u2_review_d#21','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C3',3,'ox','auto','아침별 모둠은 진다해 선생님께 감사 인사를 드리고 헤어졌으니 면담이 모두 끝났어요.',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":21,"concept":"K6-2-u2-C3","difficulty":3,"kind":"ox","stem":"아침별 모둠은 진다해 선생님께 감사 인사를 드리고 헤어졌으니 면담이 모두 끝났어요.","answer":"X","reason_options":[{"t":"들은 것을 간추리고 성찰해 보고서로 남기는 면담 정리하기가 남았기 때문에","correct":true},{"t":"감사 인사가 면담의 마지막 일이기 때문에","mis":"K6-2-u2-X05"}],"mis":"K6-2-u2-X05","explanation":["헤어진 뒤에도 할 일이 있어요.","내용 정리 · 성찰 · 보고서 쓰기예요.","다온도 「보고서가 나오면 보여 드리겠습니다」라고 했어요."],"asset":{"type":"speech","turns":[{"who":"예준","text":"책방을 하고 싶은 학생에게 해 주실 말씀이 있나요?"},{"who":"진다해","text":"책을 많이 읽는 것만큼 사람 이야기를 많이 들어 보세요."},{"who":"다온","text":"책을 고르는 일이 손님의 모습을 오래 보는 일이라는 말씀이 기억에 남습니다. 보고서가 나오면 보여 드리겠습니다. 감사합니다."}]}}'::jsonb),
('g6_2_kor_u2_review_d#22','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C9',3,'ox','auto','아침별 모둠이 보고서를 반 알림판에 붙이고 진다해 선생님께도 보여 드리는 것은 알맞아요.',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":22,"concept":"K6-2-u2-C9","difficulty":3,"kind":"ox","stem":"아침별 모둠이 보고서를 반 알림판에 붙이고 진다해 선생님께도 보여 드리는 것은 알맞아요.","answer":"O","reason_options":[{"t":"간추려 쓴 보고서는 함께 읽어도 되고 면담 대상자께 보여 드리는 것이 좋기 때문에","correct":true},{"t":"보고서에 녹음 파일을 함께 붙이면 더 좋기 때문에","mis":"K6-2-u2-X11"}],"mis":"K6-2-u2-X11","explanation":["간추려 쓴 보고서는 나눠도 돼요.","면담 대상자께 보여 드리기로 약속했어요.","담아 둔 목소리는 나누지 않아요."],"asset":{"type":"speech","turns":[{"who":"예준","text":"책방을 하고 싶은 학생에게 해 주실 말씀이 있나요?"},{"who":"진다해","text":"책을 많이 읽는 것만큼 사람 이야기를 많이 들어 보세요."},{"who":"다온","text":"책을 고르는 일이 손님의 모습을 오래 보는 일이라는 말씀이 기억에 남습니다. 보고서가 나오면 보여 드리겠습니다. 감사합니다."}]}}'::jsonb),
('g6_2_kor_u2_review_d#23','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C10',4,'mc','auto','태건과의 인물 면담에서 바람직한 질문과 작품에 근거한 답을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K6-2-u2-X17','K6-2-u2-X16']::text[],false,'{"seq":23,"concept":"K6-2-u2-C10","difficulty":4,"kind":"mc","stem":"태건과의 인물 면담에서 바람직한 질문과 작품에 근거한 답을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"질문 「혼자 돌을 옮기기로 마음먹은 까닭이 있었나요?」 — 답 「할머니가 한 시간을 돌아 다니시는 게 마음에 걸렸어요.」","correct":true},{"t":"질문 「혼자 하는 거 바보 같지 않았어요?」 — 답 「네, 바보 같았어요.」","mis":"K6-2-u2-X17"},{"t":"질문 「혼자 돌을 옮기기로 마음먹은 까닭이 있었나요?」 — 답 「상을 받으려고요.」","mis":"K6-2-u2-X16"},{"t":"질문 「왜 친구가 하나도 없었어요?」 — 답 「그건 이야기에 나오지 않습니다.」","mis":"K6-2-u2-X17"}],"explanation":["질문은 마음을 헤아려 까닭을 여쭈어요.","답은 「할머니는 … 한 시간을 돌아」 같은 이야기 속 사건에서 나와요.","둘 다 갖추어야 좋은 인물 면담이에요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb),
('g6_2_kor_u2_review_d#24','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C10',4,'essay','teacher','「사흘 걸린 다리」의 태건에게 할 질문을 세 갈래로 하나씩 만들고, 그중 하나에 태건이 되어 작품을 근거로 답해 보세요. 불쾌한 질문이 되지 않게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u2-C10","difficulty":4,"kind":"essay","stem":"「사흘 걸린 다리」의 태건에게 할 질문을 세 갈래로 하나씩 만들고, 그중 하나에 태건이 되어 작품을 근거로 답해 보세요. 불쾌한 질문이 되지 않게 쓰세요.","answer_guide":{"answer":"예: 사실 — 떠내려간 돌을 며칠 동안 옮기셨나요? 생각이나 느낌 — 쌓은 돌이 흩어졌을 때 어떤 마음이 드셨나요? 계획이나 당부 — 혼자 무언가를 시작하려는 친구에게 해 줄 말이 있나요? 답(생각이나 느낌) — 사흘 동안 쌓은 돌이 흩어져 힘이 빠졌고 젖은 모래밭에 주저앉았어요. 그런데 그때 상우 아저씨가 지게를 지고 와 「나도 좀 하자.」라고 하셔서 다시 힘이 났어요.","scoring_points":["세 갈래로 질문을 하나씩 만들었는가","질문이 상대의 마음을 헤아리는 바람직한 질문인가","작품 속 사건·행동을 근거로 답했는가"]},"explanation":["인물에게도 세 갈래로 물어요.","깎아내리지 않고 마음을 헤아려요.","답은 이야기 안에서만 찾아요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb),
('g6_2_kor_u2_review_d#25','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C11',4,'essay','teacher','「밝다」와 「굵다」에 모음으로 시작하는 말을 붙여 문장을 하나씩 만들고, 밑줄 친 말이 어떻게 소리 나는지와 그렇게 소리 나는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u2-C11","difficulty":4,"kind":"essay","stem":"「밝다」와 「굵다」에 모음으로 시작하는 말을 붙여 문장을 하나씩 만들고, 밑줄 친 말이 어떻게 소리 나는지와 그렇게 소리 나는 까닭을 쓰세요.","answer_guide":{"answer":"예: 「보름달이 밝아서 길이 잘 보인다.」에서 「밝아」는 [발가], 「나무 밑동이 굵어 안을 수 없다.」에서 「굵어」는 [굴거]로 소리 난다. 뒤에 모음으로 시작하는 말이 붙으면 겹받침의 앞 자음 ㄹ은 받침으로 남고 뒤 자음 ㄱ이 넘어가 소리 나기 때문이다.","scoring_points":["두 낱말에 모음으로 시작하는 말을 붙여 문장을 만들었는가","발음을 바르게 썼는가","앞 자음은 남고 뒤 자음이 넘어간다는 까닭을 썼는가"]},"explanation":["모음이 붙으면 뒤 자음이 넘어가요.","밝아[발가] · 굵어[굴거]예요.","낱말 하나일 때는 [박따] · [국따]예요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('K6-2-u3-C1','kor',6,2,'u3',1,'주장 · 이유 · 근거 — 주장은 어떤 주제에 대한 자신의 의견을 드러내는 말, 이유는 왜 그렇게 주장하는지를 설명하는 말, 근거는 이유를 뒷받침하는 자료나 사실이며, 셋의 자리를 갈라야 평가할 수 있다',ARRAY['6국01 듣기·말하기(초안)']::text[],1),
('K6-2-u3-C2','kor',6,2,'u3',1,'비판적으로 보고 듣기 — 무조건 믿거나 무조건 의심하는 것이 아니라 옳고 그른지를 제대로 따져 보는 것(맞는 것은 맞다고, 부족한 것은 부족하다고 까닭을 들어 말하기), 따져 보지 않으면 사실이 아닌 것을 믿고 옮기게 되고, 따져 보면 믿을 만한 정보를 골라 쓰고 내 생각과 견주어 볼 수 있다',ARRAY['6국01 듣기·말하기(초안)']::text[],2),
('K6-2-u3-C3','kor',6,2,'u3',2,'주장하는 말을 듣는 방법 — 말은 되감을 수 없으므로 메모하며 듣기(이유·근거 적기)·요약하며 듣기(주장·이유·근거로 간추리기)·견주며 듣기(내 생각과 견주기)를 하고, 지나치게 감정에 호소하지는 않는지 태도까지 살핀다',ARRAY['6국01 듣기·말하기(초안)']::text[],3),
('K6-2-u3-C4','kor',6,2,'u3',2,'주장의 타당성 판단 기준 — 주장이 가치 있고 중요한지는 문제를 해결하거나 생활하는 데 도움이 되는가, 실천 가능한가(언제 무엇을 할지 정해져 있는가)로 판단한다',ARRAY['6국01 듣기·말하기(초안)']::text[],4),
('K6-2-u3-C5','kor',6,2,'u3',2,'이유의 타당성 판단 기준 — 이유가 주장과 관련 있는가, 많은 사람이 받아들일 만한가(혼자만의 느낌·사정이 아닌가) 두 물음을 함께 통과해야 한다',ARRAY['6국01 듣기·말하기(초안)']::text[],5),
('K6-2-u3-C6','kor',6,2,'u3',2,'근거의 타당성 판단 기준과 근거 자료 — 근거가 이유와 관련 있는가, 객관적인 사실이나 정보인가로 판단하고, 근거 자료의 유형(표·그래프·면담 자료·사례)을 알며, 근거가 사실인지 책·기사·기관 누리집·어른께 여쭈어 확인하고 출처가 믿을 만한지 다시 살핀다',ARRAY['6국01 듣기·말하기(초안)']::text[],6),
('K6-2-u3-C7','kor',6,2,'u3',4,'주장하는 말의 내용을 평가하며 듣기 — 타당한 점을 먼저 찾고 보완할 점을 찾으며(평가는 이긴 쪽을 고르는 일이 아니라 더 나아지게 하는 일), 평가 기준표에 ◎·○·△로 판단하고 그렇게 판단한 까닭(어떤 기준을 더 무겁게 보았는지)을 말한다',ARRAY['6국01 듣기·말하기(초안)']::text[],7),
('K6-2-u3-C8','kor',6,2,'u3',4,'객관적인 근거와 출처 밝히기 — 누가 보아도 그러한 객관적인 근거와 혼자만의 느낌·짐작인 주관적인 말을 가르고, 주관적인 근거는 더 힘주어 말하거나 감정에 호소하지 않고 확인할 수 있는 자료로 고치며, 가져다 쓴 자료는 어디에서 나왔는지 밝힌다',ARRAY['6국01 듣기·말하기(초안)']::text[],8),
('K6-2-u3-C9','kor',6,2,'u3',7,'영상의 주장 파악하기 — 알려 주는 영상·보여 주는 영상·주장하는 영상을 가르고, 영상은 주장을 직접 말하지 않는 경우가 많으므로 제목(그렇게 정한 까닭)·제시한 자료(무엇을 보여 주려고 넣었는지)·강조하는 장면이나 표현(되풀이·음악이 멈추는 자리·글자만 남는 화면)을 합쳐 주장을 한 문장으로 세운다',ARRAY['6국06 매체(초안)']::text[],9),
('K6-2-u3-C10','kor',6,2,'u3',7,'강조와 타당성 가르기 — 음악·되풀이 자막 같은 강조는 만든 사람이 무엇을 가장 하고 싶은 말로 여기는지 알려 주는 실마리일 뿐 그 말이 타당한지·사실인지는 알려 주지 못하며, 주장을 찾는 일과 타당한지 따지는 일은 다르다(끝까지 한 번 보고 두 번째에 적으며 보기)',ARRAY['6국06 매체(초안)']::text[],10),
('K6-2-u3-C11','kor',6,2,'u3',9,'카드 뉴스 내용을 평가하며 보기 — 카드 뉴스는 첫 장의 제목과 굵은 글씨에 주장이, 가운데 장에 이유와 근거가 한 쌍씩 놓이며, 짧을수록 빠진 것이 잘 보이지 않으므로 이유마다 「그래서 왜?」, 근거마다 「이게 그 이유를 보여 주나?」를 물으며 같은 세 기준으로 평가한다',ARRAY['6국06 매체(초안)']::text[],11),
('K6-2-u3-C12','kor',6,2,'u3',9,'약한 자리 짚기와 부분 평가 — 잘 세워진 자리를 먼저 세고, 문제의 규모(많다·늘고 있다)만 말하는 이유나 이유를 보여 주지 않고 해결 방안(제도)을 말하는 근거를 약한 자리로 짚되, 하나가 약하다고 주장 전체가 틀린 것은 아니며 고칠 자리를 짚어 준다',ARRAY['6국06 매체(초안)']::text[],12),
('K6-2-u3-C13','kor',6,2,'u3',12,'영상을 골라 타당성을 평가하고 설명하기 — 여러 사람이 함께 생각해 볼 만한 주제를 정해 구체적인 말로 찾고, 자세히 보기·알아낸 것 말하기·생각하기·궁금해하기 차례로 보며, 주장이 없는 영상은 평가표에서 가려내고, 내용의 타당성을 먼저·표현은 그다음에 보고, 제목·주장·이유·근거·판단·까닭을 넣어 설명한다',ARRAY['6국06 매체(초안)']::text[],13),
('K6-2-u3-C14','kor',6,2,'u3',12,'받침 ㅎ의 발음 — 받침 ㅎ 뒤에 ㄱ·ㄷ·ㅈ이 오면 합쳐서 ㅋ·ㅌ·ㅊ으로(넣고[너코]·빨갛다[빨가타]·그렇지[그러치]), ㄴ이 오면 ㄴ으로(넣는[넌는]), 모음이 오면 ㅎ 소리를 내지 않는다(좋아[조아])(기초 다지기)',ARRAY['6국04 문법(초안)']::text[],14)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('K6-2-u3-X01','kor',6,'u3',ARRAY['K6-2-u3-C1','K6-2-u3-C9','K6-2-u3-C11']::text[],'주장 · 이유 · 근거의 자리를 섞는다(이유를 주장으로, 주장을 근거로 여기는 등)','하자는 말? 왜 그런지? 받쳐 주는 자료?'),
('K6-2-u3-X02','kor',6,'u3',ARRAY['K6-2-u3-C2','K6-2-u3-C7','K6-2-u3-C12']::text[],'비판적으로 보기를 무조건 의심하기·말한 사람 깎아내리기·어딘가 잘못이 있다고 미리 정하기로 여긴다','따져 보기 = 맞는 것은 맞다고, 부족한 것은 부족하다고'),
('K6-2-u3-X03','kor',6,'u3',ARRAY['K6-2-u3-C2','K6-2-u3-C11']::text[],'말을 잘하거나 짧고 보기 좋거나 많이 퍼진 주장을 따져 보지 않고 그대로 믿는다','「이 말, 무엇이 받쳐 주지?」'),
('K6-2-u3-X04','kor',6,'u3',ARRAY['K6-2-u3-C3']::text[],'메모하거나 간추리지 않고 들어 평가할 거리를 남기지 못하거나, 결론을 미리 정하고 목소리·말솜씨로 판단한다','말은 되감을 수 없어요 — 적고 간추리며 듣기'),
('K6-2-u3-X05','kor',6,'u3',ARRAY['K6-2-u3-C4']::text[],'말만 크고 무엇부터 할지 알 수 없는 주장도 가치 있다고 여긴다(실천 가능성을 보지 않음)','언제 · 무엇을 할지 정해져 있나?'),
('K6-2-u3-X06','kor',6,'u3',ARRAY['K6-2-u3-C5']::text[],'주장과 관련 없는 이유를 받아들이거나, 관련 있는 이유를 관련 없다고 여긴다','이 이유가 주장이 말하는 일과 이어지나?'),
('K6-2-u3-X07','kor',6,'u3',ARRAY['K6-2-u3-C5']::text[],'혼자만의 느낌이나 사정인 이유도 많은 사람이 받아들일 만한 이유로 여긴다','나만 그런가, 많은 사람이 고개를 끄덕일까?'),
('K6-2-u3-X08','kor',6,'u3',ARRAY['K6-2-u3-C6','K6-2-u3-C8']::text[],'말한 사람의 느낌이나 짐작을 근거로 여기거나, 근거는 길고 많을수록 좋다고 여긴다','누가 보아도 그러한가, 확인할 수 있나?'),
('K6-2-u3-X09','kor',6,'u3',ARRAY['K6-2-u3-C6']::text[],'근거가 사실인지 확인하지 않거나, 검색해 나온 것·많이 퍼진 글을 출처 확인 없이 믿는다','책 · 기사 · 기관 누리집 · 어른께 — 그리고 출처 한 번 더'),
('K6-2-u3-X10','kor',6,'u3',ARRAY['K6-2-u3-C6']::text[],'근거 자료의 유형(표·그래프·면담 자료·사례)과 그 쓰임을 헷갈린다','나란히 견주기? 흐름? 사람의 말? 있었던 일?'),
('K6-2-u3-X11','kor',6,'u3',ARRAY['K6-2-u3-C7','K6-2-u3-C12']::text[],'평가를 흠부터 찾는 일이나 이긴 쪽을 고르는 일로 여겨 타당한 점을 먼저 찾지 않는다','살릴 것 먼저, 고칠 것은 그다음'),
('K6-2-u3-X12','kor',6,'u3',ARRAY['K6-2-u3-C7','K6-2-u3-C13']::text[],'까닭 없이 표시만 하거나 「그냥 그렇게 느꼈다」로 판단하고, 판단이 갈릴 때 어떤 기준을 무겁게 보았는지 말하지 않는다','「나는 ○○을 가장 무겁게 보았어. 그래서 …」'),
('K6-2-u3-X13','kor',6,'u3',ARRAY['K6-2-u3-C8']::text[],'가져다 쓴 자료의 출처를 밝히지 않아 확인할 길을 막거나 남의 자료를 내 것처럼 쓴다','어디에서 · 언제 나온 자료인지 말하기'),
('K6-2-u3-X14','kor',6,'u3',ARRAY['K6-2-u3-C8']::text[],'약한 근거를 고칠 때 더 힘주어 되풀이하거나 듣는 사람의 감정에 호소한다','느낌을 키우지 말고 확인할 수 있는 자료로 바꾸기'),
('K6-2-u3-X15','kor',6,'u3',ARRAY['K6-2-u3-C9','K6-2-u3-C13']::text[],'영상의 주장을 한 요소(제목만·분위기만)로 정하거나, 주장과 관계없는 것(길이·벽 색)을 실마리로 삼거나, 알려 주는 영상과 주장하는 영상을 헷갈린다','제목 + 자료 + 강조 → 한 문장'),
('K6-2-u3-X16','kor',6,'u3',ARRAY['K6-2-u3-C9']::text[],'영상도 주장을 문장으로 직접 말할 것이라 여겨, 직접 말하지 않으면 주장이 없다고 본다','「그래서 나더러 무엇을 하라는 걸까?」'),
('K6-2-u3-X17','kor',6,'u3',ARRAY['K6-2-u3-C10']::text[],'음악이 커지고 자막이 되풀이될수록, 곧 강조가 셀수록 주장이 옳거나 사실이라고 여긴다','강조는 「무엇을」 말하고 싶은지만 알려 줘요'),
('K6-2-u3-X18','kor',6,'u3',ARRAY['K6-2-u3-C12']::text[],'문제의 규모(많다·늘고 있다)만으로 문제가 되는 까닭을 말했다고 여긴다','많아서 → 무엇이 어떻게 나빠지나?'),
('K6-2-u3-X19','kor',6,'u3',ARRAY['K6-2-u3-C12']::text[],'문제에 대한 해결 방안(제도·규칙·대책)을 그 문제가 있다는 이유를 보여 주는 근거로 여긴다','이 근거는 문제를 보여 주나, 그 뒤의 일을 말하나?'),
('K6-2-u3-X20','kor',6,'u3',ARRAY['K6-2-u3-C12']::text[],'이유나 근거 하나가 약하면 주장 전체가 틀렸다거나 믿을 수 없다고 여긴다','약한 자리는 고칠 자리 — 주장 전체와 가르기'),
('K6-2-u3-X21','kor',6,'u3',ARRAY['K6-2-u3-C13']::text[],'주장이 없는 영상도 평가표로 재거나, 음악·편집·말투 같은 표현과 재미로 타당성을 판단한다','먼저 평가할 수 있는 영상인지 · 내용 먼저, 표현은 그다음'),
('K6-2-u3-X22','kor',6,'u3',ARRAY['K6-2-u3-C13']::text[],'영상을 찾고 보는 차례를 지키지 않는다(두루뭉술하거나 자극적인 검색어, 본 것과 짐작한 것을 섞기)','구체적인 말로 찾기 · 본 것 → 생각 → 물음'),
('K6-2-u3-X23','kor',6,'u3',ARRAY['K6-2-u3-C14']::text[],'받침 ㅎ을 뒤 소리와 상관없이 그대로 소리 내거나, ㄱ·ㄷ·ㅈ과 합치지 않고 ㄷ으로 끊어 소리 낸다','ㄱ·ㄷ·ㅈ → ㅋ·ㅌ·ㅊ · ㄴ → ㄴ · 모음 → 소리 없음')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g6_2_kor_u3_L01_basic#1','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',1,'mc','auto','「주장」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":1,"concept":"K6-2-u3-C1","difficulty":1,"kind":"mc","stem":"「주장」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 주제에 대한 자신의 의견을 드러내는 말","correct":true},{"t":"왜 그렇게 주장하는지를 설명하는 말","mis":"K6-2-u3-X01"},{"t":"이유를 뒷받침하는 자료나 사실","mis":"K6-2-u3-X01"},{"t":"다른 사람의 말을 그대로 옮긴 말","mis":"K6-2-u3-X01"}],"explanation":["주장은 「무엇을 하자」는 의견이에요.","왜 그런지 밝히는 말은 이유예요.","이유를 받쳐 주는 자료는 근거예요."]}'::jsonb),
('g6_2_kor_u3_L01_basic#2','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',1,'sa','auto','이유를 뒷받침하는 자료나 사실을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C1","difficulty":1,"kind":"sa","stem":"이유를 뒷받침하는 자료나 사실을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["근거"],"explanation":["주장은 의견, 이유는 까닭이에요.","이유가 사실인지 보여 주는 자료가 있어야 해요.","그 자료나 사실을 근거라고 해요."],"mis":"K6-2-u3-X01"}'::jsonb),
('g6_2_kor_u3_L01_basic#3','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',1,'ox','auto','비판적으로 본다는 것은 무조건 믿지 않는 것이에요.',ARRAY['K6-2-u3-X02']::text[],false,'{"seq":3,"concept":"K6-2-u3-C2","difficulty":1,"kind":"ox","stem":"비판적으로 본다는 것은 무조건 믿지 않는 것이에요.","answer":"X","reason_options":[{"t":"옳고 그른지를 제대로 따져 보는 것이기 때문에","correct":true},{"t":"어떤 말이든 먼저 의심해야 속지 않기 때문에","mis":"K6-2-u3-X02"}],"mis":"K6-2-u3-X02","explanation":["무조건 믿지 않는 것은 따져 보기 전에 정해 버리는 것이에요.","비판적으로 보기는 까닭을 들어 따지는 것이에요.","맞는 것은 맞다고, 부족한 것은 부족하다고 말해요."]}'::jsonb),
('g6_2_kor_u3_L01_basic#4','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',1,'mc','auto','주장을 따져 보지 않고 그대로 믿었을 때 생길 수 있는 일은 어느 것인가요?',ARRAY['K6-2-u3-X03','K6-2-u3-X02']::text[],false,'{"seq":4,"concept":"K6-2-u3-C2","difficulty":1,"kind":"mc","stem":"주장을 따져 보지 않고 그대로 믿었을 때 생길 수 있는 일은 어느 것인가요?","options":[{"t":"사실이 아닌 것을 사실로 알게 된다","correct":true},{"t":"아무 일도 생기지 않는다","mis":"K6-2-u3-X03"},{"t":"말한 사람을 깎아내리게 된다","mis":"K6-2-u3-X02"},{"t":"글을 더 빨리 읽게 된다","mis":"K6-2-u3-X03"}],"explanation":["따져 보지 않으면 사실이 아닌 것도 그대로 믿게 돼요.","그 말을 다른 사람에게 옮길 수도 있어요.","그래서 한 번 더 따져 보아요."]}'::jsonb),
('g6_2_kor_u3_L01_basic#5','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',2,'mc','auto','서담이가 본 영상이 하려던 주장은 무엇인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":5,"concept":"K6-2-u3-C1","difficulty":2,"kind":"mc","stem":"서담이가 본 영상이 하려던 주장은 무엇인가요?","options":[{"t":"아침에 물을 두 컵 마시자","correct":true},{"t":"자는 동안 몸에서 물이 빠져나간다","mis":"K6-2-u3-X01"},{"t":"짧은 영상을 자주 보자","mis":"K6-2-u3-X01"},{"t":"물에 대한 자료를 찾아보자","mis":"K6-2-u3-X01"}],"explanation":["영상이 보는 사람에게 하라고 한 일이 주장이에요.","「물이 빠져나가기 때문」은 왜 그런지 밝힌 이유예요.","주장과 이유의 자리가 달라요."],"asset":{"type":"speech","turns":[{"who":"서담","text":"방금 본 영상에서 그러던데, 아침에 물을 두 컵 마시면 하루 종일 힘이 난대."},{"who":"하리","text":"그렇게 말한 까닭도 나왔어?"},{"who":"서담","text":"응. 자는 동안 몸에서 물이 빠져나가기 때문이래."},{"who":"하리","text":"그 말이 사실이라는 자료도 보여 주었어?"},{"who":"서담","text":"아니. 그 말만 하고 다음 장면으로 넘어갔어."}]}}'::jsonb),
('g6_2_kor_u3_L01_basic#6','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',2,'mc','auto','서담이가 본 영상에 빠져 있던 것은 어느 것인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":6,"concept":"K6-2-u3-C1","difficulty":2,"kind":"mc","stem":"서담이가 본 영상에 빠져 있던 것은 어느 것인가요?","options":[{"t":"근거 — 이유가 사실이라는 자료","correct":true},{"t":"주장 — 무엇을 하자는 말","mis":"K6-2-u3-X01"},{"t":"이유 — 그렇게 말한 까닭","mis":"K6-2-u3-X01"},{"t":"주장과 이유 모두","mis":"K6-2-u3-X01"}],"explanation":["영상에는 「물을 두 컵 마시자」는 주장이 있었어요.","「물이 빠져나가기 때문」이라는 이유도 있었어요.","그 말이 사실이라는 자료는 없었어요."],"asset":{"type":"speech","turns":[{"who":"서담","text":"방금 본 영상에서 그러던데, 아침에 물을 두 컵 마시면 하루 종일 힘이 난대."},{"who":"하리","text":"그렇게 말한 까닭도 나왔어?"},{"who":"서담","text":"응. 자는 동안 몸에서 물이 빠져나가기 때문이래."},{"who":"하리","text":"그 말이 사실이라는 자료도 보여 주었어?"},{"who":"서담","text":"아니. 그 말만 하고 다음 장면으로 넘어갔어."}]}}'::jsonb),
('g6_2_kor_u3_L01_basic#7','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',2,'match','auto','주장 · 이유 · 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u3-C1","difficulty":2,"kind":"match","stem":"주장 · 이유 · 근거를 알맞게 이으세요.","pairs":[{"l":"주장","r":"복도에서는 걸어 다닙시다"},{"l":"이유","r":"뛰면 부딪칠 수 있기 때문입니다"},{"l":"근거","r":"복도에서 부딪친 일이 여러 번 있었다는 보건실 기록"}],"mis":"K6-2-u3-X01","explanation":["무엇을 하자는 말이 주장이에요.","「~ 때문입니다」로 까닭을 밝히면 이유예요.","이유를 받쳐 주는 기록이 근거예요."]}'::jsonb),
('g6_2_kor_u3_L01_basic#8','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',2,'mc','auto','비판적으로 듣는 사람의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X03']::text[],false,'{"seq":8,"concept":"K6-2-u3-C2","difficulty":2,"kind":"mc","stem":"비판적으로 듣는 사람의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"이유와 근거가 주장과 잘 맞는지 따져 본다","correct":true},{"t":"일단 틀린 곳이 있다고 생각하고 듣는다","mis":"K6-2-u3-X02"},{"t":"말을 잘하는 사람의 말이면 그대로 받아들인다","mis":"K6-2-u3-X03"},{"t":"말한 사람이 마음에 들지 않으면 듣지 않는다","mis":"K6-2-u3-X02"}],"explanation":["믿거나 믿지 않거나 둘 중 하나로 정해 버리지 않아요.","이유와 근거가 주장과 맞는지 따져요.","말솜씨나 사람이 아니라 내용을 보아요."]}'::jsonb),
('g6_2_kor_u3_L01_basic#9','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',2,'ox','auto','주장을 따져 보면 믿을 만한 정보를 골라 쓸 수 있어요.',ARRAY['K6-2-u3-X02']::text[],false,'{"seq":9,"concept":"K6-2-u3-C2","difficulty":2,"kind":"ox","stem":"주장을 따져 보면 믿을 만한 정보를 골라 쓸 수 있어요.","answer":"O","reason_options":[{"t":"내용을 제대로 이해하고 내 생각과 견주어 볼 수 있기 때문에","correct":true},{"t":"따져 보면 모든 주장이 틀렸다는 것을 알게 되기 때문에","mis":"K6-2-u3-X02"}],"mis":"K6-2-u3-X02","explanation":["따져 보면 내용을 제대로 이해할 수 있어요.","내 생각과 견주어 볼 수 있어요.","따져 본다고 모든 주장이 틀린 것은 아니에요."]}'::jsonb),
('g6_2_kor_u3_L01_basic#10','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',3,'error','auto','비판적으로 보는 것에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X11']::text[],false,'{"seq":10,"concept":"K6-2-u3-C2","difficulty":3,"kind":"error","stem":"비판적으로 보는 것에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은솔 — 「어느 영상이든 잘못이 있게 마련이니 틀린 곳부터 찾으면 돼.」","correct":true,"mis_target":"K6-2-u3-X02"},{"t":"지호 — 「맞는 것은 맞다고, 부족한 것은 부족하다고 까닭을 들어 말하는 거야.」","mis":"K6-2-u3-X02"},{"t":"라온 — 「타당한 점을 먼저 찾고 그다음에 보완할 점을 찾아.」","mis":"K6-2-u3-X11"}],"explanation":["지호와 라온은 따져 보기를 바르게 말했어요.","은솔은 잘못이 있다고 미리 정해 두었어요.","그것은 비판이 아니라 의심이에요."]}'::jsonb),
('g6_2_kor_u3_L01_challenge#1','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',2,'mc','auto','주장이 우리를 만나는 자리에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X03']::text[],false,'{"seq":1,"concept":"K6-2-u3-C2","difficulty":2,"kind":"mc","stem":"주장이 우리를 만나는 자리에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"발표 · 영상 · 카드 뉴스 · 광고 · 누리 소통망 글 어디에나 주장이 담길 수 있다","correct":true},{"t":"발표와 연설 같은 말에만 주장이 들어 있다","mis":"K6-2-u3-X03"},{"t":"영상과 카드 뉴스는 사실만 전하므로 주장이 없다","mis":"K6-2-u3-X03"},{"t":"광고는 물건을 보여 줄 뿐 주장이 없다","mis":"K6-2-u3-X03"}],"explanation":["담는 그릇은 여러 가지예요.","영상·카드 뉴스·광고에도 주장이 담겨요.","찾는 방법은 같아요 — 주장·이유·근거."]}'::jsonb),
('g6_2_kor_u3_L01_challenge#2','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',2,'sa','auto','이유는 왜 그렇게 주장하는지를 ○○하는 말이에요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C1","difficulty":2,"kind":"sa","stem":"이유는 왜 그렇게 주장하는지를 ○○하는 말이에요. ○○에 알맞은 두 글자를 쓰세요.","answer":["설명"],"explanation":["주장은 의견을 드러내는 말이에요.","이유는 그 의견의 까닭을 설명해요.","근거는 이유를 뒷받침해요."],"mis":"K6-2-u3-X01"}'::jsonb),
('g6_2_kor_u3_L01_challenge#3','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',3,'mc','auto','하리가 「그 말이 사실이라는 자료도 보여 주었어?」라고 물은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X01','K6-2-u3-X03']::text[],false,'{"seq":3,"concept":"K6-2-u3-C1","difficulty":3,"kind":"mc","stem":"하리가 「그 말이 사실이라는 자료도 보여 주었어?」라고 물은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"이유를 뒷받침하는 근거가 있는지 따져 보려고","correct":true},{"t":"서담이의 말을 믿지 않기로 미리 정해서","mis":"K6-2-u3-X02"},{"t":"영상의 주장이 무엇인지 몰라서","mis":"K6-2-u3-X01"},{"t":"영상이 얼마나 길었는지 궁금해서","mis":"K6-2-u3-X03"}],"explanation":["하리는 먼저 이유가 있었는지 물었어요.","그다음 이유를 받쳐 줄 자료를 물었어요.","믿지 않으려는 것이 아니라 따져 보려는 물음이에요."],"asset":{"type":"speech","turns":[{"who":"서담","text":"방금 본 영상에서 그러던데, 아침에 물을 두 컵 마시면 하루 종일 힘이 난대."},{"who":"하리","text":"그렇게 말한 까닭도 나왔어?"},{"who":"서담","text":"응. 자는 동안 몸에서 물이 빠져나가기 때문이래."},{"who":"하리","text":"그 말이 사실이라는 자료도 보여 주었어?"},{"who":"서담","text":"아니. 그 말만 하고 다음 장면으로 넘어갔어."}]}}'::jsonb),
('g6_2_kor_u3_L01_challenge#4','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',3,'mc','auto','「비판적으로 보기」와 「무조건 의심하기」를 바르게 가른 것은 어느 것인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X03']::text[],false,'{"seq":4,"concept":"K6-2-u3-C2","difficulty":3,"kind":"mc","stem":"「비판적으로 보기」와 「무조건 의심하기」를 바르게 가른 것은 어느 것인가요?","options":[{"t":"비판적으로 보기는 까닭을 들어 옳고 그름을 따지고, 무조건 의심하기는 따지기 전에 믿지 않기로 정한다","correct":true},{"t":"둘은 같은 말이다","mis":"K6-2-u3-X02"},{"t":"비판적으로 보기는 말한 사람을 깎아내리는 것이다","mis":"K6-2-u3-X02"},{"t":"의심하지 않고 그대로 믿는 것이 비판적으로 보기이다","mis":"K6-2-u3-X03"}],"explanation":["의심은 따지기 전에 정해 버려요.","비판은 까닭을 들어 따져요.","그래서 맞는 것은 맞다고도 말해요."]}'::jsonb),
('g6_2_kor_u3_L01_challenge#5','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',3,'ox','auto','「복도에서 뛰면 부딪칠 수 있다」는 주장이에요.',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":5,"concept":"K6-2-u3-C1","difficulty":3,"kind":"ox","stem":"「복도에서 뛰면 부딪칠 수 있다」는 주장이에요.","answer":"X","reason_options":[{"t":"왜 걸어 다녀야 하는지를 밝힌 이유이기 때문에","correct":true},{"t":"무엇을 하자는 말이 들어 있기 때문에","mis":"K6-2-u3-X01"}],"mis":"K6-2-u3-X01","explanation":["「복도에서는 걸어 다닙시다」가 주장이에요.","「부딪칠 수 있다」는 그 까닭이에요.","그래서 이 말은 이유예요."]}'::jsonb),
('g6_2_kor_u3_L01_challenge#6','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',3,'match','auto','주장을 대하는 태도와 그 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C2","difficulty":3,"kind":"match","stem":"주장을 대하는 태도와 그 결과를 알맞게 이으세요.","pairs":[{"l":"그대로 믿는다","r":"사실이 아닌 것을 다른 사람에게 옮길 수 있다"},{"l":"무조건 의심한다","r":"맞는 말도 받아들이지 못한다"},{"l":"까닭을 들어 따진다","r":"믿을 만한 정보를 골라 쓸 수 있다"}],"mis":"K6-2-u3-X02","explanation":["그대로 믿으면 잘못된 정보도 옮겨요.","무조건 의심하면 맞는 말도 놓쳐요.","따져 보아야 골라 쓸 수 있어요."]}'::jsonb),
('g6_2_kor_u3_L01_challenge#7','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',3,'error','auto','「급식을 남기지 맙시다」의 이유와 근거를 친구들이 말했어요. 자리를 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":7,"concept":"K6-2-u3-C1","difficulty":3,"kind":"error","stem":"「급식을 남기지 맙시다」의 이유와 근거를 친구들이 말했어요. 자리를 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「근거는 ‘음식을 남기지 맙시다’야.」","correct":true,"mis_target":"K6-2-u3-X01"},{"t":"준서 — 「이유는 ‘남은 음식은 버려지기 때문이다’야.」","mis":"K6-2-u3-X01"},{"t":"가윤 — 「근거는 ‘하루에 남은 음식을 잰 우리 학교 기록’이야.」","mis":"K6-2-u3-X01"}],"explanation":["준서는 까닭을 이유로 바르게 말했어요.","가윤은 이유를 받쳐 주는 기록을 근거로 말했어요.","태린이 말한 것은 주장이에요."]}'::jsonb),
('g6_2_kor_u3_L01_challenge#8','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',4,'mc','auto','주장 · 이유 · 근거가 모두 갖추어진 말은 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X08']::text[],false,'{"seq":8,"concept":"K6-2-u3-C1","difficulty":4,"kind":"mc","stem":"주장 · 이유 · 근거가 모두 갖추어진 말은 어느 것인가요?","options":[{"t":"「계단 손잡이를 잡고 내려갑시다. 발을 헛디뎌도 버틸 수 있기 때문입니다. 손잡이를 잡은 날 덜 미끄러졌다고 답한 우리 반 조사가 있습니다.」","correct":true},{"t":"「계단 손잡이를 잡고 내려갑시다. 꼭 그렇게 합시다.」","mis":"K6-2-u3-X01"},{"t":"「계단 손잡이를 잡고 내려갑시다. 발을 헛디뎌도 버틸 수 있기 때문입니다.」","mis":"K6-2-u3-X08"},{"t":"「우리 반 조사가 있습니다. 손잡이는 차갑습니다.」","mis":"K6-2-u3-X01"}],"explanation":["첫째 보기는 주장을 되풀이했을 뿐이에요.","둘째 보기는 이유까지만 있고 근거가 없어요.","정답은 하자는 말·까닭·조사 자료를 모두 갖추었어요."]}'::jsonb),
('g6_2_kor_u3_L01_challenge#9','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',4,'essay','teacher','서담이가 본 영상의 내용을 주장 · 이유 · 근거로 나누어 쓰고, 빠진 것이 무엇인지 밝히세요. 그리고 빠진 자리를 채우려면 어떤 자료가 있으면 좋을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C1","difficulty":4,"kind":"essay","stem":"서담이가 본 영상의 내용을 주장 · 이유 · 근거로 나누어 쓰고, 빠진 것이 무엇인지 밝히세요. 그리고 빠진 자리를 채우려면 어떤 자료가 있으면 좋을지 쓰세요.","answer_guide":{"answer":"예: 주장 — 아침에 물을 두 컵 마시자. 이유 — 자는 동안 몸에서 물이 빠져나가기 때문이다. 근거 — 없다. 그 말이 사실이라는 자료를 보여 주지 않았다. 자는 동안 몸에서 물이 빠져나간다는 것을 다룬 책이나 건강 기관의 안내 자료를 보여 주면 이유가 힘을 얻을 것이다.","scoring_points":["주장과 이유를 바르게 갈라 썼는가","근거가 빠졌다는 것을 밝혔는가","확인할 수 있는 자료(책·기관 안내 등)를 들었는가"]},"explanation":["하자는 말과 까닭을 먼저 갈라요.","하리가 물은 것이 바로 빠진 자리예요.","근거는 확인할 수 있는 자료여야 해요."],"asset":{"type":"speech","turns":[{"who":"서담","text":"방금 본 영상에서 그러던데, 아침에 물을 두 컵 마시면 하루 종일 힘이 난대."},{"who":"하리","text":"그렇게 말한 까닭도 나왔어?"},{"who":"서담","text":"응. 자는 동안 몸에서 물이 빠져나가기 때문이래."},{"who":"하리","text":"그 말이 사실이라는 자료도 보여 주었어?"},{"who":"서담","text":"아니. 그 말만 하고 다음 장면으로 넘어갔어."}]}}'::jsonb),
('g6_2_kor_u3_L01_challenge#10','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',4,'essay','teacher','「비판적으로 본다는 것은 무조건 의심하는 것이다.」라는 말이 왜 알맞지 않은지 쓰고, 주장을 따져 보지 않고 그대로 믿었을 때 생길 수 있는 일을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C2","difficulty":4,"kind":"essay","stem":"「비판적으로 본다는 것은 무조건 의심하는 것이다.」라는 말이 왜 알맞지 않은지 쓰고, 주장을 따져 보지 않고 그대로 믿었을 때 생길 수 있는 일을 두 가지 쓰세요.","answer_guide":{"answer":"예: 비판적으로 본다는 것은 무조건 믿지 않는 것이 아니라 옳고 그른지를 제대로 따져 보는 것이다. 맞는 것은 맞다고, 부족한 것은 부족하다고 까닭을 들어 말하는 것이기 때문이다. 그대로 믿으면 사실이 아닌 것을 사실로 알게 되고, 그 잘못된 정보를 다른 사람에게 옮길 수 있다.","scoring_points":["따져 보기와 무조건 의심하기를 바르게 갈랐는가","맞는 것은 맞다고도 말한다는 점을 썼는가","그대로 믿었을 때의 문제를 두 가지 썼는가"]},"explanation":["의심은 따지기 전에 정해요.","비판은 까닭을 들어 따져요.","그대로 믿으면 잘못된 정보가 퍼져요."]}'::jsonb),
('g6_2_kor_u3_L02_basic#1','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C3',1,'mc','auto','주장하는 말을 들을 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":1,"concept":"K6-2-u3-C3","difficulty":1,"kind":"mc","stem":"주장하는 말을 들을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"이유와 근거를 메모하며 듣는다","correct":true},{"t":"말이 끝나기 전에 결론을 미리 정해 둔다","mis":"K6-2-u3-X04"},{"t":"말하는 사람의 목소리 크기만 보고 판단한다","mis":"K6-2-u3-X04"},{"t":"주장만 듣고 나머지는 흘려듣는다","mis":"K6-2-u3-X04"}],"explanation":["말은 되감을 수 없어요.","이유와 근거를 적어 두어야 평가할 거리가 남아요.","결론은 다 들은 뒤에 내려요."]}'::jsonb),
('g6_2_kor_u3_L02_basic#2','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C6',1,'sa','auto','실제로 있었던 일 하나를 들어 보이는 근거 자료를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C6","difficulty":1,"kind":"sa","stem":"실제로 있었던 일 하나를 들어 보이는 근거 자료를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["사례"],"explanation":["표는 값을 나란히 놓아요.","그래프는 흐름을, 면담 자료는 사람의 말을 보여 줘요.","있었던 일 하나를 들면 사례예요."],"mis":"K6-2-u3-X10"}'::jsonb),
('g6_2_kor_u3_L02_basic#3','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C4',1,'ox','auto','실천 가능한 주장이어야 가치 있는 주장이라고 할 수 있어요.',ARRAY['K6-2-u3-X05']::text[],false,'{"seq":3,"concept":"K6-2-u3-C4","difficulty":1,"kind":"ox","stem":"실천 가능한 주장이어야 가치 있는 주장이라고 할 수 있어요.","answer":"O","reason_options":[{"t":"무엇을 언제 할지 알아야 생활에서 해 볼 수 있기 때문에","correct":true},{"t":"말이 크고 멋있을수록 가치 있는 주장이기 때문에","mis":"K6-2-u3-X05"}],"mis":"K6-2-u3-X05","explanation":["주장은 문제 해결에 도움이 되어야 해요.","그리고 실천할 수 있어야 해요.","말만 크면 무엇부터 할지 알 수 없어요."]}'::jsonb),
('g6_2_kor_u3_L02_basic#4','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C6',1,'mc','auto','근거의 타당성을 판단하는 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X01']::text[],false,'{"seq":4,"concept":"K6-2-u3-C6","difficulty":1,"kind":"mc","stem":"근거의 타당성을 판단하는 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"근거가 이유와 관련 있고 객관적인 사실이나 정보인가?","correct":true},{"t":"근거가 말한 사람의 느낌을 잘 드러내는가?","mis":"K6-2-u3-X08"},{"t":"근거가 길고 어려운 말로 되어 있는가?","mis":"K6-2-u3-X08"},{"t":"근거가 주장보다 먼저 나오는가?","mis":"K6-2-u3-X01"}],"explanation":["근거는 이유를 받쳐 주어야 해요.","느낌이나 짐작은 근거가 되지 못해요.","누가 보아도 그러한 사실이어야 해요."]}'::jsonb),
('g6_2_kor_u3_L02_basic#5','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C3',2,'mc','auto','민율이의 말을 주장 · 이유 · 근거로 나누어 간추릴 때, 주장으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X04']::text[],false,'{"seq":5,"concept":"K6-2-u3-C3","difficulty":2,"kind":"mc","stem":"민율이의 말을 주장 · 이유 · 근거로 나누어 간추릴 때, 주장으로 알맞은 것은 어느 것인가요?","options":[{"t":"모르는 것은 그날 안에 물어보자","correct":true},{"t":"모르는 것을 그대로 두면 다음에 배울 것까지 막힌다","mis":"K6-2-u3-X01"},{"t":"예담이는 분수의 뜻을 몰라 여러 단원에서 어려워했다","mis":"K6-2-u3-X01"},{"t":"묻는 일은 부끄러운 일이다","mis":"K6-2-u3-X04"}],"explanation":["「그날 안에 물어보자」가 하자는 말이에요.","「막히기 때문」은 이유, 예담이 이야기는 근거예요.","「부끄러운 일이다」는 민율이가 한 말과 반대예요."],"asset":{"type":"passage","lines":["저는 모르는 것은 그날 안에 물어보자고 말하고 싶습니다.","모르는 것을 그대로 두면 다음에 배울 것까지 막히기 때문입니다.","배움은 앞의 것 위에 뒤의 것이 쌓이는 일이라, 아래가 비면 위가 흔들립니다.","예담이는 분수의 뜻을 잘 모른 채로 넘어갔다가 여러 단원에서 어려워했습니다.","다시 물어보고 처음부터 확인한 뒤에야 막힌 곳이 풀렸습니다.","우리 반에서 조사해 보니, 궁금한 것을 물어본 날에는","다음 날 수업이 더 쉬웠다고 답한 사람이 훨씬 많았습니다.","묻는 일은 부끄러운 일이 아닙니다. 오늘부터 그날 안에 물어봅시다."],"title":"민율이의 주장하는 말 「그날의 물음」"}}'::jsonb),
('g6_2_kor_u3_L02_basic#6','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C5',2,'mc','auto','「모르는 것은 그날 안에 물어보자」를 뒷받침하는 이유로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X07','K6-2-u3-X06']::text[],false,'{"seq":6,"concept":"K6-2-u3-C5","difficulty":2,"kind":"mc","stem":"「모르는 것은 그날 안에 물어보자」를 뒷받침하는 이유로 알맞은 것은 어느 것인가요?","options":[{"t":"다음에 배울 것까지 막히기 때문이다","correct":true},{"t":"나는 손을 드는 것이 재미있기 때문이다","mis":"K6-2-u3-X07"},{"t":"수업 시간은 사십 분이기 때문이다","mis":"K6-2-u3-X06"},{"t":"선생님 목소리가 크기 때문이다","mis":"K6-2-u3-X06"}],"explanation":["이유는 주장과 이어져야 해요.","많은 사람이 받아들일 만해야 해요.","「막히기 때문」은 누구에게나 해당하고 주장과 곧바로 이어져요."]}'::jsonb),
('g6_2_kor_u3_L02_basic#7','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C6',2,'match','auto','근거 자료의 유형과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u3-C6","difficulty":2,"kind":"match","stem":"근거 자료의 유형과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"표","r":"여러 값을 나란히 놓아 견주게 해 준다"},{"l":"그래프","r":"늘고 주는 흐름을 한눈에 보여 준다"},{"l":"면담 자료","r":"그 일을 겪은 사람의 말을 그대로 옮긴다"},{"l":"사례","r":"실제로 있었던 일 하나를 들어 보인다"}],"mis":"K6-2-u3-X10","explanation":["표는 나란히, 그래프는 흐름이에요.","면담 자료는 사람의 말이에요.","사례는 있었던 일 하나예요."]}'::jsonb),
('g6_2_kor_u3_L02_basic#8','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C4',2,'mc','auto','더 실천 가능한 주장은 어느 것인가요?',ARRAY['K6-2-u3-X05']::text[],false,'{"seq":8,"concept":"K6-2-u3-C4","difficulty":2,"kind":"mc","stem":"더 실천 가능한 주장은 어느 것인가요?","options":[{"t":"잠자기 전에 열 쪽씩 책을 읽읍시다","correct":true},{"t":"우리 모두 훌륭한 사람이 됩시다","mis":"K6-2-u3-X05"},{"t":"세상을 더 좋게 만듭시다","mis":"K6-2-u3-X05"},{"t":"언젠가는 책을 많이 읽읍시다","mis":"K6-2-u3-X05"}],"explanation":["언제 무엇을 할지 정해져 있어야 실천할 수 있어요.","「잠자기 전에 열 쪽씩」은 오늘 바로 할 수 있어요.","말이 크면 무엇부터 할지 알 수 없어요."]}'::jsonb),
('g6_2_kor_u3_L02_basic#9','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C5',2,'ox','auto','「학교 도서관에 책을 더 사자. 내가 읽고 싶은 책이 아직 없기 때문이다.」의 이유는 많은 사람이 받아들일 만해요.',ARRAY['K6-2-u3-X07']::text[],false,'{"seq":9,"concept":"K6-2-u3-C5","difficulty":2,"kind":"ox","stem":"「학교 도서관에 책을 더 사자. 내가 읽고 싶은 책이 아직 없기 때문이다.」의 이유는 많은 사람이 받아들일 만해요.","answer":"X","reason_options":[{"t":"주장과 관련은 있지만 한 사람의 사정이라 많은 사람이 고개를 끄덕이기 어렵기 때문에","correct":true},{"t":"주장과 관련이 있으면 타당한 이유이기 때문에","mis":"K6-2-u3-X07"}],"mis":"K6-2-u3-X07","explanation":["이 이유는 주장과 관련은 있어요.","그러나 한 사람이 읽고 싶은 책 이야기예요.","두 물음 가운데 하나만 통과했어요."]}'::jsonb),
('g6_2_kor_u3_L02_basic#10','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C6',3,'error','auto','근거로 나온 말이 사실인지 확인하는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X09']::text[],false,'{"seq":10,"concept":"K6-2-u3-C6","difficulty":3,"kind":"error","stem":"근거로 나온 말이 사실인지 확인하는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하엘 — 「누리집에서 한 번 검색해서 나온 기사면 그대로 믿으면 돼.」","correct":true,"mis_target":"K6-2-u3-X09"},{"t":"도하 — 「그 내용을 다룬 책이나 기사를 찾아보고 출처도 살펴봐.」","mis":"K6-2-u3-X09"},{"t":"세아 — 「그 일을 맡은 기관의 누리집에서 확인하거나 어른께 여쭈어.」","mis":"K6-2-u3-X09"}],"explanation":["책·기사·기관 누리집·어른께 여쭙기가 모두 방법이에요.","찾은 기사도 어디에서 나왔는지 한 번 더 살펴요.","검색 한 번으로 끝내면 확인한 것이 아니에요."]}'::jsonb),
('g6_2_kor_u3_L02_challenge#1','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C3',2,'sa','auto','주장 · 이유 · 근거로 나누어 간추리며 듣는 것을 「○○하며 듣기」라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u3-C3","difficulty":2,"kind":"sa","stem":"주장 · 이유 · 근거로 나누어 간추리며 듣는 것을 「○○하며 듣기」라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["요약"],"explanation":["메모하며 듣기는 적으며 들어요.","요약하며 듣기는 간추리며 들어요.","견주며 듣기는 내 생각과 견주어요."],"mis":"K6-2-u3-X04"}'::jsonb),
('g6_2_kor_u3_L02_challenge#2','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C4',2,'mc','auto','주장이 가치 있고 중요한지 판단하는 두 물음을 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u3-X05','K6-2-u3-X01','K6-2-u3-X03']::text[],false,'{"seq":2,"concept":"K6-2-u3-C4","difficulty":2,"kind":"mc","stem":"주장이 가치 있고 중요한지 판단하는 두 물음을 바르게 모은 것은 어느 것인가요?","options":[{"t":"문제를 해결하거나 생활하는 데 도움이 되는가 · 실천 가능한가","correct":true},{"t":"말이 멋있는가 · 길이가 적당한가","mis":"K6-2-u3-X05"},{"t":"주장과 관련 있는가 · 객관적인가","mis":"K6-2-u3-X01"},{"t":"말한 사람이 유명한가 · 목소리가 큰가","mis":"K6-2-u3-X03"}],"explanation":["주장은 도움이 되는지와 실천 가능한지로 재요.","「관련 있는가」는 이유와 근거를 재는 물음이에요.","말한 사람이나 말솜씨는 기준이 아니에요."]}'::jsonb),
('g6_2_kor_u3_L02_challenge#3','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C6',3,'mc','auto','「그날의 물음」의 근거를 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X01']::text[],false,'{"seq":3,"concept":"K6-2-u3-C6","difficulty":3,"kind":"mc","stem":"「그날의 물음」의 근거를 바르게 모은 것은 어느 것인가요?","options":[{"t":"예담이의 사례와 우리 반 조사 결과","correct":true},{"t":"묻는 일은 부끄러운 일이 아니라는 말","mis":"K6-2-u3-X08"},{"t":"배움은 앞의 것 위에 뒤의 것이 쌓인다는 말","mis":"K6-2-u3-X01"},{"t":"오늘부터 그날 안에 물어보자는 말","mis":"K6-2-u3-X01"}],"explanation":["근거는 이유를 받쳐 주는 자료나 사실이에요.","예담이 이야기는 사례, 반 조사는 조사 결과예요.","「쌓이는 일」은 이유를 풀어 준 설명이에요."],"asset":{"type":"passage","lines":["저는 모르는 것은 그날 안에 물어보자고 말하고 싶습니다.","모르는 것을 그대로 두면 다음에 배울 것까지 막히기 때문입니다.","배움은 앞의 것 위에 뒤의 것이 쌓이는 일이라, 아래가 비면 위가 흔들립니다.","예담이는 분수의 뜻을 잘 모른 채로 넘어갔다가 여러 단원에서 어려워했습니다.","다시 물어보고 처음부터 확인한 뒤에야 막힌 곳이 풀렸습니다.","우리 반에서 조사해 보니, 궁금한 것을 물어본 날에는","다음 날 수업이 더 쉬웠다고 답한 사람이 훨씬 많았습니다.","묻는 일은 부끄러운 일이 아닙니다. 오늘부터 그날 안에 물어봅시다."],"title":"민율이의 주장하는 말 「그날의 물음」"}}'::jsonb),
('g6_2_kor_u3_L02_challenge#4','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C6',3,'mc','auto','민율이가 근거를 「우리 반 친구의 사례」와 「우리 반에서 조사한 결과」로 든 것이 좋은 까닭은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X14','K6-2-u3-X09']::text[],false,'{"seq":4,"concept":"K6-2-u3-C6","difficulty":3,"kind":"mc","stem":"민율이가 근거를 「우리 반 친구의 사례」와 「우리 반에서 조사한 결과」로 든 것이 좋은 까닭은 어느 것인가요?","options":[{"t":"듣는 사람이 확인할 수 있는 객관적인 사실이어서","correct":true},{"t":"말한 사람의 느낌이 잘 드러나서","mis":"K6-2-u3-X08"},{"t":"듣는 사람의 마음을 세게 움직여서","mis":"K6-2-u3-X14"},{"t":"확인할 수 없어서 따질 수 없어서","mis":"K6-2-u3-X09"}],"explanation":["같은 반 친구는 예담이에게 물어볼 수 있어요.","반 조사 결과도 다시 확인할 수 있어요.","확인할 수 있어야 객관적인 근거예요."],"asset":{"type":"passage","lines":["저는 모르는 것은 그날 안에 물어보자고 말하고 싶습니다.","모르는 것을 그대로 두면 다음에 배울 것까지 막히기 때문입니다.","배움은 앞의 것 위에 뒤의 것이 쌓이는 일이라, 아래가 비면 위가 흔들립니다.","예담이는 분수의 뜻을 잘 모른 채로 넘어갔다가 여러 단원에서 어려워했습니다.","다시 물어보고 처음부터 확인한 뒤에야 막힌 곳이 풀렸습니다.","우리 반에서 조사해 보니, 궁금한 것을 물어본 날에는","다음 날 수업이 더 쉬웠다고 답한 사람이 훨씬 많았습니다.","묻는 일은 부끄러운 일이 아닙니다. 오늘부터 그날 안에 물어봅시다."],"title":"민율이의 주장하는 말 「그날의 물음」"}}'::jsonb),
('g6_2_kor_u3_L02_challenge#5','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C5',3,'ox','auto','이유가 주장과 관련만 있으면 타당한 이유라고 할 수 있어요.',ARRAY['K6-2-u3-X07']::text[],false,'{"seq":5,"concept":"K6-2-u3-C5","difficulty":3,"kind":"ox","stem":"이유가 주장과 관련만 있으면 타당한 이유라고 할 수 있어요.","answer":"X","reason_options":[{"t":"많은 사람이 받아들일 만한지도 함께 따져야 하기 때문에","correct":true},{"t":"이유는 주장과 이어지기만 하면 되기 때문에","mis":"K6-2-u3-X07"}],"mis":"K6-2-u3-X07","explanation":["이유를 재는 물음은 두 가지예요.","주장과 관련 있는가, 많은 사람이 받아들일 만한가.","하나만 통과하면 약한 이유예요."]}'::jsonb),
('g6_2_kor_u3_L02_challenge#6','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C4',3,'match','auto','무엇의 타당성인지와 그것을 재는 물음을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C4","difficulty":3,"kind":"match","stem":"무엇의 타당성인지와 그것을 재는 물음을 알맞게 이으세요.","pairs":[{"l":"주장","r":"문제 해결에 도움이 되고 실천 가능한가"},{"l":"이유","r":"주장과 관련 있고 많은 사람이 받아들일 만한가"},{"l":"근거","r":"이유와 관련 있고 객관적인 사실이나 정보인가"}],"mis":"K6-2-u3-X01","explanation":["주장은 가치와 실천 가능성을 보아요.","이유는 주장과의 관련과 받아들일 만함을 보아요.","근거는 이유와의 관련과 객관성을 보아요."]}'::jsonb),
('g6_2_kor_u3_L02_challenge#7','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C3',3,'error','auto','주장하는 말을 듣는 태도를 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":7,"concept":"K6-2-u3-C3","difficulty":3,"kind":"error","stem":"주장하는 말을 듣는 태도를 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"나린 — 「말은 다시 들을 수 없으니 그냥 느낌만 기억하면 돼.」","correct":true,"mis_target":"K6-2-u3-X04"},{"t":"유찬 — 「말은 되감을 수 없으니 이유와 근거를 메모하며 들어.」","mis":"K6-2-u3-X04"},{"t":"보미 — 「지나치게 감정에 호소하지는 않는지도 살피며 들어.」","mis":"K6-2-u3-X04"}],"explanation":["말은 한 번 듣고 지나가요.","그래서 적고 간추리며 들어야 평가할 거리가 남아요.","느낌만 남기면 따질 수 없어요."]}'::jsonb),
('g6_2_kor_u3_L02_challenge#8','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C6',4,'mc','auto','「동네 놀이터에 그늘막을 세우자. 여름 한낮에 놀이 기구가 뜨거워지기 때문이다.」의 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X06']::text[],false,'{"seq":8,"concept":"K6-2-u3-C6","difficulty":4,"kind":"mc","stem":"「동네 놀이터에 그늘막을 세우자. 여름 한낮에 놀이 기구가 뜨거워지기 때문이다.」의 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여름 한낮에 놀이 기구의 뜨거운 정도를 시간마다 재어 적은 표","correct":true},{"t":"나는 그늘에서 노는 것을 좋아한다는 말","mis":"K6-2-u3-X08"},{"t":"그늘막은 예쁜 색이 많다는 말","mis":"K6-2-u3-X06"},{"t":"이웃 동네 놀이터가 더 넓다는 사례","mis":"K6-2-u3-X06"}],"explanation":["이유는 「놀이 기구가 뜨거워진다」예요.","그것을 보여 주는 자료가 근거예요.","시간마다 잰 표는 이유와 관련 있고 객관적이에요."]}'::jsonb),
('g6_2_kor_u3_L02_challenge#9','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C5',4,'essay','teacher','「모르는 것은 그날 안에 물어보자」를 뒷받침하는 이유를 하나 더 만들어 쓰고, 그 이유가 이유를 재는 두 물음을 통과하는지 하나씩 따져 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C5","difficulty":4,"kind":"essay","stem":"「모르는 것은 그날 안에 물어보자」를 뒷받침하는 이유를 하나 더 만들어 쓰고, 그 이유가 이유를 재는 두 물음을 통과하는지 하나씩 따져 쓰세요.","answer_guide":{"answer":"예: 이유 — 궁금한 것을 바로 물어보면 그날 배운 내용이 머릿속에 또렷하게 남기 때문이다. 이 이유는 「물어보자」는 주장과 곧바로 이어지므로 주장과 관련 있다. 또 나 혼자만의 사정이 아니라 수업을 듣는 누구에게나 해당하므로 많은 사람이 받아들일 만하다.","scoring_points":["주장과 이어지는 이유를 새로 만들었는가","주장과 관련 있는지 따졌는가","많은 사람이 받아들일 만한지 따졌는가"]},"explanation":["이유는 주장과 이어져야 해요.","나만의 느낌이 아니어야 해요.","두 물음을 하나씩 대어 보아요."],"asset":{"type":"passage","lines":["저는 모르는 것은 그날 안에 물어보자고 말하고 싶습니다.","모르는 것을 그대로 두면 다음에 배울 것까지 막히기 때문입니다.","배움은 앞의 것 위에 뒤의 것이 쌓이는 일이라, 아래가 비면 위가 흔들립니다.","예담이는 분수의 뜻을 잘 모른 채로 넘어갔다가 여러 단원에서 어려워했습니다.","다시 물어보고 처음부터 확인한 뒤에야 막힌 곳이 풀렸습니다.","우리 반에서 조사해 보니, 궁금한 것을 물어본 날에는","다음 날 수업이 더 쉬웠다고 답한 사람이 훨씬 많았습니다.","묻는 일은 부끄러운 일이 아닙니다. 오늘부터 그날 안에 물어봅시다."],"title":"민율이의 주장하는 말 「그날의 물음」"}}'::jsonb),
('g6_2_kor_u3_L02_challenge#10','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C6',4,'essay','teacher','「그날의 물음」의 근거 가운데 하나를 골라 근거의 유형을 쓰고, 그 근거가 사실인지 확인하는 방법을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C6","difficulty":4,"kind":"essay","stem":"「그날의 물음」의 근거 가운데 하나를 골라 근거의 유형을 쓰고, 그 근거가 사실인지 확인하는 방법을 두 가지 쓰세요.","answer_guide":{"answer":"예: 「궁금한 것을 물어본 날에는 다음 날 수업이 더 쉬웠다고 답한 사람이 많았다」는 우리 반 조사 결과로, 표로 나타낼 수 있는 자료이다. 사실인지 확인하려면 조사한 종이나 표를 직접 보여 달라고 하거나, 반 친구들에게 다시 물어 조사해 볼 수 있다.","scoring_points":["근거를 하나 골라 유형을 바르게 썼는가","확인 방법을 두 가지 썼는가","확인 방법이 그 근거에 알맞은가"]},"explanation":["조사 결과는 표나 그래프로 보여 줄 수 있어요.","사례는 겪은 사람에게 물어볼 수 있어요.","확인할 수 있어야 믿을 수 있어요."],"asset":{"type":"passage","lines":["저는 모르는 것은 그날 안에 물어보자고 말하고 싶습니다.","모르는 것을 그대로 두면 다음에 배울 것까지 막히기 때문입니다.","배움은 앞의 것 위에 뒤의 것이 쌓이는 일이라, 아래가 비면 위가 흔들립니다.","예담이는 분수의 뜻을 잘 모른 채로 넘어갔다가 여러 단원에서 어려워했습니다.","다시 물어보고 처음부터 확인한 뒤에야 막힌 곳이 풀렸습니다.","우리 반에서 조사해 보니, 궁금한 것을 물어본 날에는","다음 날 수업이 더 쉬웠다고 답한 사람이 훨씬 많았습니다.","묻는 일은 부끄러운 일이 아닙니다. 오늘부터 그날 안에 물어봅시다."],"title":"민율이의 주장하는 말 「그날의 물음」"}}'::jsonb),
('g6_2_kor_u3_L04_basic#1','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C7',1,'mc','auto','주장하는 말을 평가하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X11','K6-2-u3-X12']::text[],false,'{"seq":1,"concept":"K6-2-u3-C7","difficulty":1,"kind":"mc","stem":"주장하는 말을 평가하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"타당한 점을 먼저 찾고 그다음에 보완할 점을 찾는다","correct":true},{"t":"흠부터 찾고 타당한 점은 찾지 않는다","mis":"K6-2-u3-X11"},{"t":"이긴 쪽을 고르고 끝낸다","mis":"K6-2-u3-X11"},{"t":"표시만 하고 까닭은 말하지 않는다","mis":"K6-2-u3-X12"}],"explanation":["흠부터 찾으면 어느 발표에나 잘못이 있다고 여기게 돼요.","타당한 점을 먼저 찾아요.","그래야 무엇을 살리고 고칠지 함께 보여요."]}'::jsonb),
('g6_2_kor_u3_L04_basic#2','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C8',1,'sa','auto','자기 생각이 아니라 누가 보아도 그러한 것을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C8","difficulty":1,"kind":"sa","stem":"자기 생각이 아니라 누가 보아도 그러한 것을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["객관적"],"explanation":["자기 혼자만의 느낌에 치우친 것은 주관적이에요.","누가 보아도 그러한 것은 객관적이에요.","근거는 객관적이어야 해요."],"mis":"K6-2-u3-X08"}'::jsonb),
('g6_2_kor_u3_L04_basic#3','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C8',1,'ox','auto','조사한 자료를 근거로 쓸 때에는 어디에서 나온 자료인지 밝혀야 해요.',ARRAY['K6-2-u3-X13']::text[],false,'{"seq":3,"concept":"K6-2-u3-C8","difficulty":1,"kind":"ox","stem":"조사한 자료를 근거로 쓸 때에는 어디에서 나온 자료인지 밝혀야 해요.","answer":"O","reason_options":[{"t":"듣는 사람이 사실인지 확인할 수 있고 남의 자료를 내 것처럼 쓰지 않게 되기 때문에","correct":true},{"t":"출처를 밝히면 말이 길어져 설득력이 떨어지기 때문에","mis":"K6-2-u3-X13"}],"mis":"K6-2-u3-X13","explanation":["출처를 밝히지 않으면 확인할 길이 없어요.","남이 만든 자료를 내 것처럼 쓰게 돼요.","「○○에서 조사한 표입니다」처럼 밝혀요."]}'::jsonb),
('g6_2_kor_u3_L04_basic#4','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C7',1,'mc','auto','다경이와 세온이가 학교 도서관에 대해 발표한 목적은 무엇인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X11']::text[],false,'{"seq":4,"concept":"K6-2-u3-C7","difficulty":1,"kind":"mc","stem":"다경이와 세온이가 학교 도서관에 대해 발표한 목적은 무엇인가요?","options":[{"t":"학교 도서관을 바꾸자고 듣는 사람을 설득하려고","correct":true},{"t":"자기가 읽은 책을 소개하려고","mis":"K6-2-u3-X01"},{"t":"도서관이 어디에 있는지 알려 주려고","mis":"K6-2-u3-X01"},{"t":"누가 더 말을 잘하는지 겨루려고","mis":"K6-2-u3-X11"}],"explanation":["두 발표는 모두 도서관을 더 낫게 만들자는 말이에요.","설득하려는 말이니 주장하는 말이에요.","겨루기가 아니라 설득이에요."]}'::jsonb),
('g6_2_kor_u3_L04_basic#5','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C1',2,'mc','auto','다경이의 발표에서 이유로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":5,"concept":"K6-2-u3-C1","difficulty":2,"kind":"mc","stem":"다경이의 발표에서 이유로 알맞은 것은 어느 것인가요?","options":[{"t":"수업이 끝난 뒤에는 책을 볼 시간이 있는 학생이 적기 때문이다","correct":true},{"t":"점심시간에도 도서관을 열어야 한다","mis":"K6-2-u3-X01"},{"t":"이용하고 싶은 시간을 조사한 표","mis":"K6-2-u3-X01"},{"t":"이웃 학교 소식지에 실린 내용","mis":"K6-2-u3-X01"}],"explanation":["「열어야 한다」는 주장이에요.","「~ 때문입니다」로 밝힌 까닭이 이유예요.","조사한 표와 소식지 내용은 근거예요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관을 점심시간에도 열어야 한다고 생각합니다.","수업이 끝난 뒤에는 도서관에 남아 책을 볼 시간이 있는 학생이 적기 때문입니다.","하교 시간이 되면 대부분 바로 집이나 다른 곳으로 가야 합니다.","우리 학교 도서관에서 조사한 표를 보면, 이용하고 싶은 시간으로","점심시간을 고른 학생이 다른 시간을 고른 학생보다 훨씬 많았습니다.","이웃 학교는 점심시간에 문을 연 뒤로 찾는 학생이 눈에 띄게 늘었다고 합니다.","학교 소식지에 실린 내용입니다.","점심시간에 도서관을 열면 더 많은 학생이 책을 만날 수 있습니다."],"title":"다경이의 발표"}}'::jsonb),
('g6_2_kor_u3_L04_basic#6','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C8',2,'mc','auto','세온이의 근거가 객관적이지 않은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X05','K6-2-u3-X06']::text[],false,'{"seq":6,"concept":"K6-2-u3-C8","difficulty":2,"kind":"mc","stem":"세온이의 근거가 객관적이지 않은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"새 책 냄새를 좋아한다는 느낌과 사람이 많아 보였다는 짐작에 머물러 있어서","correct":true},{"t":"근거가 너무 짧아서","mis":"K6-2-u3-X08"},{"t":"주장이 학생들에게 도움이 되지 않아서","mis":"K6-2-u3-X05"},{"t":"이유가 주장과 관련이 없어서","mis":"K6-2-u3-X06"}],"explanation":["「좋아합니다」는 세온이의 느낌이에요.","「많아 보였습니다」는 짐작이에요.","누가 보아도 그러한 것이 아니에요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관에 새 책을 더 많이 사야 한다고 생각합니다.","새 책이 많아야 학생들이 도서관에 오기 때문입니다.","저는 새 책 냄새를 좋아합니다. 새 책이 있으면 도서관에 가고 싶어집니다.","지난달에 도서관에 갔을 때 새로 들어온 책이 놓인 칸에","사람이 많아 보였습니다.","그러니 도서관에 새 책을 더 많이 사 주면 좋겠습니다."],"title":"세온이의 발표"}}'::jsonb),
