('g6_2_kor_u3_review_b#9','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C1',2,'match','auto','윤채가 한 말의 자리와 그 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C1","difficulty":2,"kind":"match","stem":"윤채가 한 말의 자리와 그 내용을 알맞게 이으세요.","pairs":[{"l":"주장","r":"쉬는 시간마다 교실 창문을 열자"},{"l":"첫째 이유","r":"닫아 두면 공기가 탁해져 머리가 무거워진다"},{"l":"첫째 근거","r":"공기 측정기로 잰 수치가 내려갔다"}],"mis":"K6-2-u3-X01","explanation":["하자는 말이 주장이에요.","「~ 때문입니다」가 이유예요.","측정한 수치가 근거예요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb),
('g6_2_kor_u3_review_b#10','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C5',2,'mc','auto','윤채의 둘째 이유 「창문을 열면 기분이 상쾌해지기 때문입니다」를 평가한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X06','K6-2-u3-X08','K6-2-u3-X20']::text[],false,'{"seq":10,"concept":"K6-2-u3-C5","difficulty":2,"kind":"mc","stem":"윤채의 둘째 이유 「창문을 열면 기분이 상쾌해지기 때문입니다」를 평가한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"주장과 관련은 있지만 느낌이라 사람마다 달라 많은 사람이 받아들이기에 약하다","correct":true},{"t":"주장과 아무 관련이 없다","mis":"K6-2-u3-X06"},{"t":"누가 보아도 그러한 사실이라 아주 튼튼하다","mis":"K6-2-u3-X08"},{"t":"이유가 약하니 주장 전체가 틀렸다","mis":"K6-2-u3-X20"}],"explanation":["창문을 여는 일과 이어지니 관련은 있어요.","그러나 상쾌함은 사람마다 달라요.","하나만 통과한 이유예요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb),
('g6_2_kor_u3_review_b#11','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C8',2,'ox','auto','남이 만든 자료를 출처 없이 쓰면 그 자료를 내 것처럼 쓰게 돼요.',ARRAY['K6-2-u3-X13']::text[],false,'{"seq":11,"concept":"K6-2-u3-C8","difficulty":2,"kind":"ox","stem":"남이 만든 자료를 출처 없이 쓰면 그 자료를 내 것처럼 쓰게 돼요.","answer":"O","reason_options":[{"t":"누가 만든 자료인지 밝히지 않으면 듣는 사람은 내가 만든 것으로 알기 때문에","correct":true},{"t":"자료는 쓰는 사람의 것이 되기 때문에","mis":"K6-2-u3-X13"}],"mis":"K6-2-u3-X13","explanation":["가져다 쓴 자료는 어디에서 왔는지 밝혀요.","그래야 남의 것을 내 것처럼 쓰지 않아요.","듣는 사람도 확인할 수 있어요."]}'::jsonb),
('g6_2_kor_u3_review_b#12','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C9',2,'mc','auto','「걸을 땐, 고개를 들어요」에 장면 2의 조사 화면을 넣은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":12,"concept":"K6-2-u3-C9","difficulty":2,"kind":"mc","stem":"「걸을 땐, 고개를 들어요」에 장면 2의 조사 화면을 넣은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"걸으며 화면을 보는 문제가 우리 가까이에 실제로 있다는 것을 보여 주려고","correct":true},{"t":"학교가 얼마나 큰지 알려 주려고","mis":"K6-2-u3-X15"},{"t":"화면을 보는 것이 재미있다는 것을 알리려고","mis":"K6-2-u3-X15"},{"t":"영상을 길게 만들려고","mis":"K6-2-u3-X15"}],"explanation":["자료를 넣은 자리에는 까닭이 있어요.","조사 화면은 문제가 있다는 것을 보여 줘요.","우리 학교 앞이라 더 가깝게 느껴져요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb),
('g6_2_kor_u3_review_b#13','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C11',2,'mc','auto','「가까운 층은 계단으로」의 주장은 무엇인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":13,"concept":"K6-2-u3-C11","difficulty":2,"kind":"mc","stem":"「가까운 층은 계단으로」의 주장은 무엇인가요?","options":[{"t":"삼 층까지는 계단으로 다니자","correct":true},{"t":"승강기를 없애자","mis":"K6-2-u3-X01"},{"t":"계단을 새로 칠하자","mis":"K6-2-u3-X01"},{"t":"승강기를 기다린 시간을 재자","mis":"K6-2-u3-X01"}],"explanation":["첫머리의 「다닙시다」가 주장이에요.","승강기를 없애자는 말은 없어요.","시간을 잰 것은 근거예요."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"}}'::jsonb),
('g6_2_kor_u3_review_b#14','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C12',2,'ox','auto','제도가 마련되어 있다는 것은 문제가 왜 생기는지를 보여 주는 근거예요.',ARRAY['K6-2-u3-X19']::text[],false,'{"seq":14,"concept":"K6-2-u3-C12","difficulty":2,"kind":"ox","stem":"제도가 마련되어 있다는 것은 문제가 왜 생기는지를 보여 주는 근거예요.","answer":"X","reason_options":[{"t":"제도는 문제에 대한 해결 방안이라 문제가 왜 생기는지는 보여 주지 못하기 때문에","correct":true},{"t":"제도가 있다는 것은 문제가 생기는 까닭을 말해 주기 때문에","mis":"K6-2-u3-X19"}],"mis":"K6-2-u3-X19","explanation":["제도는 이미 나선 답이에요.","근거는 이유를 보여 주어야 해요.","해결 방안은 그 뒤의 일이에요."]}'::jsonb),
('g6_2_kor_u3_review_b#15','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C13',2,'ox','auto','가장 타당한 영상을 고르면 그 활동은 끝나요.',ARRAY['K6-2-u3-X12']::text[],false,'{"seq":15,"concept":"K6-2-u3-C13","difficulty":2,"kind":"ox","stem":"가장 타당한 영상을 고르면 그 활동은 끝나요.","answer":"X","reason_options":[{"t":"왜 그것을 골랐는지 말로 세울 수 있을 때 끝나기 때문에","correct":true},{"t":"고르는 것이 평가의 끝이기 때문에","mis":"K6-2-u3-X12"}],"mis":"K6-2-u3-X12","explanation":["고르는 것이 끝이 아니에요.","판단한 까닭을 말로 세워야 해요.","그래야 친구가 따라올 수 있어요."]}'::jsonb),
